import type { Chapter } from '../../types'

// HI fact bank. Authored from the official HI study text (8th Ed, Dec 2024),
// grounded strictly in the ebook across all 15 chapters.
export const hiChapters: Chapter[] = [
  {
    id: 'h1',
    num: 1,
    title: 'Overview Of Healthcare Environment In Singapore',
    page: 1,
    concepts: [
      { id: 'h1-01', term: 'Singapore Government healthcare philosophy (5 objectives)', fact: 'Through MOH, the Government manages healthcare on five objectives: (1) nurture a healthy nation by promoting good health; (2) promote personal responsibility for one\'s health and avoid over-reliance on state welfare or medical insurance; (3) provide good and affordable basic medical services to all Singaporeans; (4) rely on competition and market forces to improve service quality and raise efficiency; (5) intervene directly when necessary should market failures lead to unsustainable growth of healthcare costs.', trap: 'Objective 2 stresses avoiding over-reliance on state welfare AND medical insurance, not just welfare.' },
      { id: 'h1-02', term: 'Healthcare 2020 Masterplan', fact: 'Launched in 2012, the Healthcare 2020 Masterplan aimed to improve healthcare access with a focus on capacity and affordability. Its three key strategies were Improved Accessibility, Improved Quality, and Enhanced Affordability.', trap: 'Healthcare 2020 launched 2012, not 2020. The 3 Beyonds (2016) came after.' },
      { id: 'h1-03', term: 'MediShield Life launch', fact: 'MediShield Life was launched in 2015 as the national basic health insurance scheme (under the Enhanced Affordability strategy of Healthcare 2020). It covers large hospitalisation bills and selected costly outpatient treatments for all Singaporeans, including the elderly and those with pre-existing conditions.', trap: 'MediShield Life = 2015; CareShield Life = 2020. Do not confuse the two launch years.' },
      { id: 'h1-04', term: 'Pioneer and Merdeka Generation packages', fact: 'The Pioneer Generation (PG) package was launched in 2014 and the Merdeka Generation (MG) package in 2019. They give seniors MediSave top-ups, additional outpatient subsidies, and additional MediShield Life premium subsidies.', trap: 'PG = 2014, MG = 2019. Easy to swap.' },
      { id: 'h1-05', term: 'Beyond Healthcare 2020 - the 3 Beyonds', fact: 'In 2016 MOH embarked on the 3 Beyonds for Better Health, Better Care and Better Life: Beyond Healthcare to Health, Beyond Hospital to Community, and Beyond Quality to Value. Six regional health systems were reorganised into three fully integrated clusters in 2017.', trap: 'Three clusters (from six regional systems), not three Beyonds equalling three clusters.' },
      { id: 'h1-06', term: 'CareShield Life launch under Beyond Hospital to Community', fact: 'CareShield Life was launched in 2020 as a national long-term care insurance scheme providing basic financial protection for long-term care costs, especially in old age. It covers all Singaporeans born in 1980 or after, including those with pre-existing disabilities; those born before 1980 may opt in.', trap: 'CareShield Life covers those born 1980 or after (compulsory); pre-1980 may opt in.' },
      { id: 'h1-07', term: 'Healthier SG', fact: 'Launched in mid-2023, Healthier SG is a multi-year strategy to promote preventive care. Its five key features are: mobilise family doctors; develop health plans; activate community partners; launch a national enrolment exercise (one family doctor + health plan); and establish enablers (IT, manpower, financing).', trap: 'Healthier SG funding shifts clusters from a workload-based to a capitation-based model; each cluster cares for about 1.5 million residents.' },
      { id: 'h1-08', term: 'Three main types of healthcare services', fact: 'Singapore\'s healthcare system has three main types of services: (a) Primary healthcare services and facilities; (b) Hospital services; (c) Intermediate and Long-Term Care (ILTC) services.', trap: 'Dental, TCM and support services are \'Other Healthcare Services\', not one of the three main types.' },
      { id: 'h1-09', term: 'Primary healthcare and CHAS', fact: 'Primary healthcare (basic treatment, preventive care, health education) is delivered through polyclinics and private GP clinics. Under the Community Health Assist Scheme (CHAS), eligible Singapore Citizens get subsidised treatment at participating GPs and dental clinics. CHAS card colours (Blue, Orange, Green) indicate the subsidy tier.', trap: 'CHAS tiers are Blue, Orange and Green. The card colour signals the subsidy level.' },
      { id: 'h1-10', term: 'Public vs private hospital beds and clusters', fact: 'Public hospitals account for 85% of all hospital beds; the private sector accounts for 15%. Public hospitals are structured into three clusters: NUHS, NHG and SingHealth. There are ten public hospitals (eight general hospitals, one women\'s and children\'s hospital, one psychiatry hospital).', trap: 'Public = 85%, private = 15%. Three clusters: NUHS, NHG, SingHealth.' },
      { id: 'h1-11', term: 'Ward class subsidies (public hospitals)', fact: 'Within public hospitals, subsidies depend on chosen ward class. Class B2 and C wards (basic amenities) enjoy heavy subsidies of up to 80%. Class B1 admissions are subsidised at 20%, while there is no subsidy for Class A. Private hospitals receive no Government subsidy.', trap: 'B2/C up to 80%; B1 = 20%; Class A = 0% subsidy. B1 is only 20%, not higher.' },
      { id: 'h1-12', term: 'Community hospitals and restructured hospitals', fact: 'There are currently nine community hospitals (rehabilitation and continuing care after acute discharge), run by VWOs or healthcare clusters. The Government has restructured all acute hospitals and specialty centres into government-owned private companies, managed as non-profit organisations receiving an annual Government subvention.', trap: 'Restructured hospitals are government-owned PRIVATE companies but run as non-profits with subvention.' },
      { id: 'h1-13', term: 'Intermediate and Long-Term Care (ILTC) service types', fact: 'ILTC services are for elderly needing care after discharge or frail community-dwelling seniors, and give caregiver respite. The four types are: home-based services, centre-based services, residential care facilities (chronic sick hospitals, nursing homes, inpatient hospices, rehabilitation/sheltered homes), and palliative care services.', trap: 'Residential care facilities cover day AND night; centre-based is usually daytime only.' },
      { id: 'h1-14', term: 'Affordable care - Flexi-MediSave and chronic conditions', fact: 'Flexi-MediSave lets seniors use an additional S$300 per year for outpatient treatment at public healthcare institutions and CHAS GP clinics. Individuals may withdraw up to S$700 per year for outpatient treatment of 23 chronic conditions (up from 20 previously). Subsidy enhancements let some specialist patients pay up to 40% less; outpatient drug subsidies up to 50% less.', trap: 'Flexi-MediSave = S$300/year; chronic condition withdrawal = S$700/year for 23 conditions. Do not swap these figures.' },
    ],
  },
  {
    id: 'h2',
    num: 2,
    title: 'Medical Expense Insurance',
    page: 12,
    concepts: [
      { id: 'h2-01', term: 'Three categories of Health Insurance', fact: 'Health Insurance provides financial benefits to defray medical costs from injury, illness or disability, in three categories: (a) reimbursement of medical treatment/care cost; (b) a periodic income upon disability or hospitalisation; or (c) a lump sum upon disability or suffering a major illness or surgery.', trap: 'Reimbursement, periodic income, and lump sum. Medical Expense Insurance is the reimbursement type.' },
      { id: 'h2-02', term: 'What is Medical Expense Insurance', fact: 'Medical Expense Insurance, also known as Hospital and Surgical (H&S) Insurance, provides inpatient and some outpatient benefits, including complex surgery (heart bypass, organ transplant) and costly outpatient treatments (kidney dialysis, chemotherapy). Examples: MediSave-approved Integrated Shield Plans (IPs), MediShield Life Scheme, and Managed Healthcare Schemes.', trap: 'Medical Expense Insurance = H&S Insurance. It covers some outpatient (major) treatment, not inpatient only.' },
      { id: 'h2-03', term: 'Accident inpatient dental and living donor transplant conditions', fact: 'Accident inpatient dental treatment (to restore sound natural teeth lost in an accident) must be received within 31 days following the accident. Living donor organ transplant (kidney or liver) requires the transplant to be in a Singapore hospital, the recipient to be the insured\'s family member (parent, sibling, spouse or child), and the recipient\'s failure first diagnosed after a 24-month waiting period.', trap: 'Accident dental = within 31 days; living donor recipient\'s failure must be diagnosed after a 24-month waiting period.' },
      { id: 'h2-04', term: 'Major organ transplant coverage', fact: 'Major organ transplant covers surgery to transplant kidneys, lungs, heart, liver, skin, cornea or musculoskeletal tissue where the insured person is the recipient. The benefit is NOT payable if the transplantation is illegal or arises from any illegal transaction or practice.', trap: 'Not payable if the transplant is illegal, regardless of medical need.' },
      { id: 'h2-05', term: 'Major outpatient treatment (kidney dialysis / cancer)', fact: 'Major outpatient treatment covers outpatient kidney dialysis, outpatient cancer drug treatment on the Cancer Drug List (CDL), outpatient cancer drug services (payable even for non-CDL treatment), outpatient radiotherapy, and major organ transplant approved immunosuppressant drugs. Dialysis excludes purchase/rental of the dialysis machine and non-prescribed solutions (except erythropoietin).', trap: 'Cancer drug TREATMENT must be on the CDL; cancer drug SERVICES are payable even for non-CDL treatments.' },
      { id: 'h2-06', term: 'Reimbursement basis and no multiple recovery', fact: 'Medical Expense Insurance pays on a reimbursement basis: the insurer reimburses the actual amount incurred (for as-charged plans) or the Schedule of Benefits limit, whichever is lower. Unlike life insurance, a policyholder cannot recover the same medical expense from multiple Medical Expense Insurance policies.', trap: 'Cannot make a profit or double-recover on medical expenses, unlike life insurance sums assured.' },
      { id: 'h2-07', term: 'Stand-alone and family coverage', fact: 'In Singapore, Medical Expense Insurance is offered as a stand-alone policy. Most policies allow inclusion of immediate family members (spouse and children), and some insurers offer a family discount (e.g. 5%) if applications are submitted at the same time.', trap: 'It is stand-alone in Singapore. Family discount example is 5%.' },
      { id: 'h2-08', term: 'Three expense participation methods', fact: 'The three expense participation methods are deductible, co-insurance and pro-ration factor. All Integrated Shield Plans, including MediShield Life Scheme, come with these features. Plans with no expense participation cost more and are payable by cash (not MediSave approved).', trap: 'Deductible, co-insurance, pro-ration factor. All three exist in all IPs including MediShield Life.' },
      { id: 'h2-09', term: 'Deductible definition and ward tiering', fact: 'A deductible is a flat dollar amount the policy owner must pay out of pocket before the insurer pays, usually per year. It is tiered to Class of Ward, e.g. Class C S$1,500, Class B2/B2+ S$2,000, Class B1 S$2,500, Class A and private hospital S$3,500. The higher the ward class, the higher the deductible.', trap: 'Higher ward class = higher deductible. Class A/private = S$3,500, not the lowest.' },
      { id: 'h2-10', term: 'Three types of deductibles', fact: 'The three deductible types are: per annum deductible (all eligible expenses in a policy year count toward it; most common in Singapore); per disability/per year deductible (same illness/injury within the same policy year); and per disability/per claim deductible (most restrictive, borne for each claim regardless of policy year).', trap: 'Per annum is the most common and most generous; per claim (per disability) is the most restrictive.' },
      { id: 'h2-11', term: 'Co-insurance', fact: 'After the deductible is satisfied, co-insurance requires the policy owner to pay a specified percentage (e.g. 10%) of the total covered medical expenses in excess of the deductible. This helps reduce over-consumption. Deductible applies separately to each insured family member (cannot be combined).', trap: 'Co-insurance applies to expenses ABOVE the deductible, not the whole bill. Deductibles are per-person, not shared.' },
      { id: 'h2-12', term: 'Pro-ration factor', fact: 'When the insured is admitted to a hospital/ward higher than the entitled plan, a pro-ration factor percentage is applied to the actual covered charges, reducing the benefit to reflect differences in Government subsidies. This ensures fairness so lower-premium payers are encouraged to use their plan\'s ward type.', trap: 'Pro-ration reduces the benefit because you chose a higher ward than your plan allows; it reflects lost subsidy.' },
      { id: 'h2-13', term: 'Three main types of benefit limits', fact: 'The three main benefit limits are: Lifetime limit (max total reimbursement over the insured\'s lifetime, e.g. S$1,000,000; policy terminates once reached), Annual limit (max reimbursement per calendar/policy year), and Event limit (max payable per disability or illness under a single claim). Sub-limits apply to individual benefit items (e.g. room and board S$300/day).', trap: 'Event limit = per disability/illness. As-charged benefits have no sub-limit but still have lifetime and annual limits.' },
      { id: 'h2-14', term: 'Geographical limit', fact: 'Most Individual Medical Expense Insurance policies automatically terminate if the insured resides outside Singapore for more than a specified period (e.g. 180 days). Some insurers only terminate if the insured is not a Singapore Citizen or SPR. Overseas medical expenses are usually reimbursed based on reasonable and customary Singapore charges.', trap: 'The example residency threshold is 180 days for individual medical expense policies.' },
      { id: 'h2-15', term: 'Waiting period', fact: 'A waiting period is a period stated in the policy that must pass before some or all coverage begins; the insurer only pays claims after it. The waiting period is NOT applicable for accidental injury (accidents are covered immediately). It guards against moral hazard and short-term join-and-cancel behaviour.', trap: 'Waiting period does NOT apply to accidental injury. May apply to pre-existing conditions and maternity.' },
      { id: 'h2-16', term: 'Age limits, premiums and renewability', fact: 'Policies issue from as young as 15 days old up to a maximum entry age (e.g. 74 or 75); children can be covered under a parent\'s policy to age 18 or 25 if in full-time tertiary education. Premiums are age-banded and increase with age, not guaranteed, adjustable with advance notice (e.g. 30 days). All IP policies are guaranteed renewable.', trap: 'Entry from 15 days old to about 74/75. Children to 18, or 25 if in full-time tertiary study. All IPs are guaranteed renewable.' },
      { id: 'h2-17', term: 'Common exclusions', fact: 'Common exclusions include: pre-existing conditions present in a specified period (e.g. 12 months) before inception; congenital anomalies; cosmetic surgery, dental and vision care; general check-ups; pregnancy/childbirth complications (unless covered); mental disorders, drug addiction, alcoholism; AIDS/STDs; aerial/hazardous sports; war/riot; self-inflicted injury; hospital-type equipment purchase; obesity/weight treatment.', trap: 'Pre-existing conditions example look-back is 12 months. Fare-paying commercial flights are NOT excluded (only non-scheduled flying is).' },
      { id: 'h2-18', term: 'Co-ordination of Benefits Clause', fact: 'Most Medical Expense Insurance policies carry a Co-ordination of Benefits Clause ensuring total claims cannot exceed total actual medical expenses incurred. If the policy owner obtains payment from other sources (e.g. employer\'s Group H&S or Work Injury Compensation), the insurer\'s payable amount is reduced.', trap: 'This is a limitation, not an exclusion. It prevents total benefits exceeding actual expenses.' },
      { id: 'h2-19', term: 'Underwriting sources and citizenship factor', fact: 'The main underwriting source for individual cover is the proposal form; for group cover the employer completes a Group Insurance Fact-Finding (GIFF) Form, and small groups (e.g. below 10 members) may need individual health declarations. Because citizens, SPRs and foreigners are subsidised differently, some insurers apply a citizenship factor (a percentage applied to a non-Singaporean insured\'s claimable expenses).', trap: 'GIFF Form = group underwriting source. Citizenship factor applies to non-Singaporeans\' claimable expenses.' },
      { id: 'h2-20', term: 'Subsidy levels for acute inpatient care (Appendix 2C)', fact: 'Only Singaporeans and PRs get public hospital subsidies. Class B2+ subsidy: Citizens 35-50%, PRs 15-25%. Class B2/C subsidy: Citizens 50-80%, PRs 25-50%. Foreigners are not subsidised. Subsidy depends on ward class, resident status, and means-testing (monthly per capita household income or property annual value).', trap: 'Citizens always get more than PRs; B2/C citizens up to 80%, PRs up to 50%. Foreigners get nothing.' },
      { id: 'h2-21', term: 'Termination of cover and claim documents', fact: 'Cover terminates on: death; entering full-time military service (except NS reservist/training under Enlistment Act 1970); end of policy period when max age attained (e.g. 80); policy termination; expiry of last paid premium period; lifetime limit reached; or (group only) cessation as an employee. Claim documents: claim form, physician\'s statement, discharge summary, and original medical bills; notify insurer within a period (e.g. 90 days).', trap: 'Cessation as an employee applies to GROUP policies only. Claim notification example is within 90 days.' },
      { id: 'h2-22', term: 'Notice No: MAS 117 - Training and Competency (Health Insurance)', fact: 'MAS 117 sets minimum examination requirements to advise on/arrange health insurance products (must pass the SCI health insurance module) plus CPD requirements for shield plans. A minimum of 2 hours of structured CPD training on MediShield Life/shield plan content is required before each calendar year end. Records must be retained for 5 years.', trap: 'CPD for shield plans is a minimum of 2 hours per calendar year; records kept for 5 years.' },
    ],
  },
  {
    id: 'h3',
    num: 3,
    title: 'Group Hospital And Surgical Insurance',
    page: 50,
    concepts: [
      { id: 'h3-01', term: 'Group Insurance eligibility criterion', fact: 'Group Insurance provides coverage to many people under one master policy. Several people must first be members of a group before they can buy the insurance, and the group must have been formed for a purpose other than obtaining insurance (e.g. companies, trade unions, professional associations, clubs).', trap: 'The group must exist for reasons other than getting insurance; you cannot form a group just to buy cover.' },
      { id: 'h3-02', term: 'Characteristics of Group Insurance', fact: 'Characteristics: Master Contract (single contract held by the employer/association; a member leaving only ends that member\'s cover); Minimal Underwriting Requirements; Experience-rating (priced on the group\'s past claims); Cost Effectiveness (low cost, one policy); Plan Continuation (usually yearly renewable); and Eligibility Requirements (e.g. full-time, age 16-65, Singaporean/SPR/valid EP).', trap: 'Experience-rating = pricing on the group\'s OWN past claims history.' },
      { id: 'h3-03', term: 'Actively-at-work clause', fact: 'Group Insurance policies have an actively-at-work clause requiring an employee to be actively at work on the day coverage takes effect to be eligible. An employee on sick leave or annual leave on that day will not be covered.', trap: 'Being on annual leave (not just sick leave) on the effective day means no coverage under the actively-at-work clause.' },
      { id: 'h3-04', term: 'Individual vs Group Insurance (key differences)', fact: 'Individual insurance: each owner gets a policy, chooses coverage, is underwritten individually, premium is age-related and higher. Group insurance: one master contract, coverage often set by employer, group underwritten as a whole (age/gender mix, occupation, claims experience), premium is unit-related and lower. Group cover stops when a member leaves but the plan continues.', trap: 'Individual premium is age-related; Group premium is unit-related.' },
      { id: 'h3-05', term: 'Compulsory vs Voluntary plans', fact: 'A compulsory (non-contributory) plan covers all eligible employees with premiums paid solely by the employer. A voluntary (contributory) plan does not require full participation; employees may pay part of the premium, and the insurer usually requires a minimum participation (e.g. 75%).', trap: 'Compulsory = non-contributory (employer pays all). Voluntary = contributory; typical minimum participation is 75%.' },
      { id: 'h3-06', term: 'Advantages of compulsory vs voluntary plans', fact: 'Compulsory plan advantages: ease of administration (no payroll deductions), lower costs (less admin, greater risk pooling), and greater employer control of benefit structure. Voluntary plan advantages: employees share costs and appreciate the plan; employees gain some control and get lower premiums than buying individually.', trap: 'Greater risk-pooling and employer control are compulsory-plan advantages.' },
      { id: 'h3-07', term: 'Migrant worker medical insurance requirement', fact: 'Since 1 January 2008 subsidies on hospital bills for foreigners were removed. MOM requires every employer to buy, pay and maintain minimum Medical Insurance for foreign workers and foreign domestic workers throughout their stay. It is compulsory for every S Pass and Work Permit holder before MOM issues or renews the work permit.', trap: 'Foreigner hospital subsidies removed from 1 January 2008. Insurance is compulsory before MOM issues/renews the permit.' },
      { id: 'h3-08', term: 'Enhanced migrant worker MI (Stage 1 / Stage 2)', fact: 'From 1 July 2023 (Stage 1): higher annual claim limit of at least S$60,000, with co-payment of 75% by insurers and 25% by employers for claim amounts above S$15,000. From 1 July 2025 (Stage 2): standardisation of exclusion clauses, age-differentiated premiums (aged 50 and below vs above 50), and insurers must reimburse hospitals directly on claim admissibility.', trap: 'Above S$15,000, insurers pay 75% and employers co-pay 25%. Annual limit at least S$60,000.' },
      { id: 'h3-09', term: 'Migrant worker co-payment arrangement', fact: 'Employers may have a co-payment arrangement with a Work Permit holder (excluding migrant domestic workers) if: the co-pay is reasonable and does not exceed 10% of the employee\'s monthly salary; co-payment duration does not exceed six months (for every 2 years of employment); and the option is explicit in the contract/collective agreement with the worker\'s full consent.', trap: 'Co-pay excludes migrant domestic workers; capped at 10% of monthly salary and 6 months per 2 years of employment.' },
      { id: 'h3-10', term: 'Portable medical benefits and 2% tax deduction', fact: 'Since 1 April 2004, employers implementing any portable medical benefits option get higher tax deduction for medical expenses of up to 2% of total employees\' remuneration. Options: Portable Medical Benefits Scheme (PMBS), Transferable Medical Insurance Scheme (TMIS), Provision of a Shield Plan, or Ad-hoc MediSave contributions. Otherwise the deduction stays at 1%.', trap: 'Portable options raise the tax deduction cap from 1% to 2% of total remuneration.' },
      { id: 'h3-11', term: 'Portable Medical Benefits Scheme (PMBS)', fact: 'Under PMBS, instead of GHS cover the employer makes additional monthly contributions to employees\' MediSave accounts, used to pay MediShield Life or IP premiums. Surplus accumulates with interest. Coverage continues even when unemployed/between jobs as long as premiums are paid.', trap: 'PMBS = employer contributes to MediSave; employee buys the policy. Cover follows the employee, not the job.' },
      { id: 'h3-12', term: 'PMBS tax deduction conditions', fact: 'To get the 2% tax deduction under PMBS the employer must: cover at least 20% of local employees (as at day one of the financial year plus new hires that year); for full-time employees, contribute at least 1% of gross monthly salary subject to a minimum of S$16 per calendar month; and for part-time employees, contribute 1% of actual gross monthly salary.', trap: 'At least 20% of local employees; minimum S$16/month for full-timers. Part-timers work under 30 hours a week.' },
      { id: 'h3-13', term: 'TMIS overview', fact: 'The Transferable Medical Insurance Scheme (TMIS) is an enhanced GHS that extends inpatient coverage for up to 12 months when an employee leaves employment. It has two features: continuation of coverage and transferability of benefits. It sits outside the CPF MediSave framework.', trap: 'TMIS continuation is up to 12 months from termination; the employer (not employee) buys the GHS policy.' },
      { id: 'h3-14', term: 'TMIS qualifying conditions', fact: 'To qualify for TMIS the employer must: have a group of 11 or more employees; take up a GHS plan; insure at least 50% (X/Y x 100%) of local employees, subject to a minimum of 11; pay 100% of the GHS premium (may recover continuation-benefit premiums from employees by agreement); and not give employees the option of whether to be insured.', trap: 'TMIS needs 11+ employees AND at least 50% of local employees insured (min 11). Employer pays 100% of premium.' },
      { id: 'h3-15', term: 'TMIS continuation vs transferability benefits', fact: 'Continuation of coverage: an employee whose employment ends (by employer or self) keeps hospitalisation cover for up to 12 months (not exceeding prescribed statutory age). Transferability: an employee moving between two TMIS-holding employers gets automatic cover under the new plan (no health evidence) plus waiver of pre-existing exclusions if continuously insured under TMIS for 12 months before joining.', trap: 'Transferability only applies TMIS-to-TMIS. Pre-existing waiver needs 12 months continuous TMIS coverage.' },
      { id: 'h3-16', term: 'TMIS pre-existing lower benefit and eligibility', fact: 'If hospitalised for a pre-existing condition within the first 12 months under a new employer\'s plan, the employee gets the LOWER entitlement of the new or prior employer\'s TMIS plan. Eligible employees must be below statutory retirement age, a Singapore Citizen or SPR based in Singapore, working full-time, on a permanent contract or a temporary contract of 24 months or more.', trap: 'First-12-months pre-existing benefit = the LOWER of the two employers\' plans. Temporary contract must be 24 months or more.' },
      { id: 'h3-17', term: 'TMIS special benefits and claims', fact: 'Qualifying TMIS medical expenses: daily room and board, ICU charges, miscellaneous hospital services, in-hospital doctor\'s visits, and inpatient/outpatient benefits. NOT eligible: pre/post-hospitalisation outpatient, emergency outpatient accident, and outpatient kidney dialysis/cancer treatment. Continuation claims are paid from the previous employer\'s TMIS plan; transferability claims from the new employer\'s plan. The employer issues a Transferable Medical Insurance Certification (TMIC).', trap: 'Outpatient dialysis/cancer and pre/post-hospital outpatient are NOT eligible for TMIS benefits.' },
      { id: 'h3-18', term: 'PMBS vs TMIS key differences', fact: 'PMBS: employer contributes to MediSave, employee buys a MediSave-approved plan (e.g. IP), coverage often lifetime, continues between jobs, has deductibles/co-insurance, pre-existing typically excluded, employer has no control. TMIS: employer buys any non-MediSave GHS policy, coverage expires at statutory retirement age, continues up to 12 months after termination, rarely has deductibles/co-insurance, pre-existing waiver allowed, employer retains full control.', trap: 'PMBS coverage can be lifetime (IP); TMIS coverage expires at statutory retirement age (or 12 months post-termination).' },
      { id: 'h3-19', term: 'Providing a Shield Plan and ad-hoc MediSave contributions', fact: 'An employer providing an IP can claim up to 2% tax deduction if it provides an IP for at least 20% of local employees and pays premiums directly to the insurer or reimburses employees\' MediSave (excludes IP rider premiums covering deductibles/co-insurance). Ad-hoc MediSave contributions get additional deduction beyond 1%, subject to a limit of S$2,730 per employee per year, with overall deduction capped at 2%.', trap: 'Ad-hoc MediSave contribution deduction limit is S$2,730 per employee per year; rider premiums are excluded from IP deduction.' },
    ],
  },
  {
    id: 'h4',
    num: 4,
    title: 'Disability Income Insurance',
    page: 63,
    concepts: [
      { id: 'h4-01', term: 'What is Disability Income Insurance', fact: 'Disability Income Insurance is income-protection replacing a portion of lost income when the insured cannot work due to accident or illness. It is also called Permanent Health Insurance because the insurer cannot cancel it no matter how many claims are made. It pays until the insured returns to work, dies, the benefit period ends, or the policy ends, whichever is first.', trap: 'Also known as Permanent Health Insurance; the insurer cannot cancel due to claims.' },
      { id: 'h4-02', term: 'Disability Income vs Total and Permanent Disability (TPD)', fact: 'Disability Income Insurance replaces income if the insured cannot work, pays monthly for up to a benefit period, is pegged to salary (up to 75%), offers escalation and partial disability benefits, and is available only to those with earned income. TPD accelerates the death benefit under a Life policy, pays a lump sum, is not pegged to salary, has no escalation or partial benefit, and covers non-working people (children, housewives).', trap: 'DII = monthly, salary-pegged (75%), earned-income only. TPD = lump sum, not salary-pegged, covers non-workers.' },
      { id: 'h4-03', term: 'Benefit computation - 75% ceiling', fact: 'Insurers allow the benefit to cover only up to 75% of the insured\'s average income over the past 12 months immediately prior to disability. A ceiling on income covered may apply (e.g. S$15,000) and a self-employed person may get a lower percentage (e.g. 60%). Capping at under 100% ensures the insured is not better off and keeps the incentive to return to work.', trap: 'Maximum is 75% of past 12 months\' average income; self-employed may only get about 60%.' },
      { id: 'h4-04', term: 'Total disability - Own Occupation', fact: 'Under Own Occupation, total disability means \'the insured\'s inability to perform the material duties of his own occupation\' at the time disability begins. Example: a pianist who severs fingers cannot work as a pianist, so she qualifies. The insurer must be notified of any occupation change while the policy is in force.', trap: 'Own Occupation is the most generous definition; based on the insured\'s own job at disability onset.' },
      { id: 'h4-05', term: 'Total disability - Modified Own and Any Occupation', fact: 'Modified Own Occupation: inability to perform any gainful or similar occupation for which the insured is reasonably suited by education, training or experience (more stringent than Own Occupation because it includes a similar occupation). Any Occupation: the insured\'s inability to perform any occupation (the most restrictive).', trap: 'Order of strictness: Own < Modified Own < Any Occupation. Any Occupation is the hardest to claim under.' },
      { id: 'h4-06', term: 'Total disability - Severe Disability (ADLs)', fact: 'Severe Disability follows the LTC definition: the insured is unable to perform at least three of the six Activities of Daily Living (ADLs) - washing, dressing, feeding, toileting, mobility, and transferring. This definition is used when disability occurs during a non-working period, and the benefit is a smaller pre-determined amount (not last-drawn salary).', trap: 'Severe disability = unable to do at least 3 of 6 ADLs. Used during non-working periods with a fixed lower benefit.' },
      { id: 'h4-07', term: 'Partial disability', fact: 'Partial disability is when the insured recovers from total disability and can do some duties of his occupation but at a salary at least 25% lower than pre-disability (i.e. earning 75% or less of pre-disability earnings). Example: Walter\'s pay dropped from S$2,500 to S$1,800 (72%, a 28% reduction), so he is partially disabled.', trap: 'Partial disability requires income to fall to 75% or less of pre-disability earnings (at least a 25% drop).' },
      { id: 'h4-08', term: 'Recurrent disability (linked claims)', fact: 'If an insured who received disability benefits returns to work but relapses from the same cause within a specified period (usually 180 days), most insurers waive the deferred/elimination period and resume payments immediately. The claim is treated as a continuation of the earlier claim for benefit-period duration purposes.', trap: 'Recurrent disability relapse window is usually 180 days; the deferred period is then waived.' },
      { id: 'h4-09', term: 'Benefit period vs deferred/elimination period', fact: 'Benefit period is the maximum period disability benefits are payable for any one episode of disability; short term (e.g. 5 years) or long term (e.g. to age 65). Deferred/elimination period is the period the insured must be disabled before benefits start (e.g. 45, 90 or 180 days, or by months). Longer deferred period = cheaper premium; shorter benefit period = cheaper premium.', trap: 'Longer deferred period AND shorter benefit period both LOWER the premium.' },
      { id: 'h4-10', term: 'Eligibility criteria for benefit payment', fact: 'To be eligible, the insured must: keep the policy in force; be employed or between jobs when disabled; still be disabled after the deferred/elimination period; meet the policy\'s total/partial disability definition; not have reached the expiry age; not have resided outside Singapore beyond a set period (usually not more than six months); and not have other income sources exceeding the benefits due.', trap: 'Being between jobs is allowed; residing overseas beyond about six months is not.' },
      { id: 'h4-11', term: 'Partial disability benefit formula', fact: 'Partial Disability Benefit (also called Rehabilitation Benefit) = [(Pre-disability Earnings - Present Earnings) / Pre-disability Earnings] x Total Disability Benefit. Example: Larry earned S$8,000, total benefit S$6,000, later earned S$1,000; benefit = (8,000-1,000)/8,000 x 6,000 = S$5,250.', trap: 'Denominator is Pre-disability Earnings; numerator is the earnings drop. Present total (benefit + new pay) is still below pre-disability income.' },
      { id: 'h4-12', term: 'Escalation benefit', fact: 'Escalation benefit is a hedge against inflation: with additional premium the insured can opt for a 3% or 5% escalation per annum, useful for long-term disabilities. Escalation applies to the benefit before partial-disability computation (e.g. S$6,000 becomes S$6,180 after 3%, then partial formula applies).', trap: 'Escalation options are 3% or 5% per annum; it is applied before the partial-disability formula.' },
      { id: 'h4-13', term: 'Waiver of premium and death benefit', fact: 'Premiums due are waived during the disability benefit payout period (both total and partial disability); if paid annually in advance, waiver starts from the next premium due date and premiums already paid are not refunded. Most insurers also pay a lump-sum death benefit to the insured\'s dependants on death.', trap: 'Prepaid annual premiums are not refunded; the waiver only starts from the next due date.' },
      { id: 'h4-14', term: 'Limitation of Disability Benefit Clause', fact: 'The limitation clause prevents over-insuring by restricting the monthly benefit so total benefits (including other disability policies) do not exceed pre-disability earnings. Benefit is reduced by payments from other disability policies (except TPD under Life policies), including Work Injury Compensation, and any continuing salary/commission from the insured\'s occupation.', trap: 'TPD benefits under Life policies are EXCLUDED from the reduction; Work Injury Compensation is included.' },
      { id: 'h4-15', term: 'Features of a Disability Income Insurance policy', fact: 'Key features: stand-alone or rider; monthly income during total/partial disablement; premiums waived during benefit period; usually guaranteed renewable and non-cancellable (insurer may adjust rates on riskier occupation change); no surrender value; no assignment; cannot be a third-party policy; benefits are non-taxable; policy lapses if premium unpaid within the 30-day grace period.', trap: 'No surrender value, no assignment, benefits non-taxable, 30-day grace period.' },
      { id: 'h4-16', term: 'Underwriting documents (employee vs self-employed)', fact: 'Salaried employee: proposal form plus Notice of Assessment or CPF Statement (six months) and a large-amount questionnaire if annual benefit exceeds a threshold (e.g. S$60,000), plus a medical test report. Self-employed: proposal form plus Notice of Assessment for the last three years or audited company accounts for three years, and large-amount questionnaire, plus medical test report.', trap: 'Self-employed need THREE years of Notice of Assessment/audited accounts; large-amount questionnaire threshold example is S$60,000.' },
      { id: 'h4-17', term: 'Occupation rating classes', fact: 'Class I: sedentary indoor professions (accountants, doctors, lawyers) - standard rating. Class II: office-based with travel/supervisory (insurance reps, tour guides, journalists). Class III: light skilled manual (bakers, deliverymen, hawkers). Class IV: semi/unskilled medium-heavy manual (bus drivers, airline crew, armed guards). Decline (uninsurable): very heavy/dangerous/variable-income (construction workers, oil riggers, divers, musicians, authors).', trap: 'Class I is standard; Classes II-IV pay extra. Musicians and authors fall under Decline (uninsurable), not a rated class.' },
      { id: 'h4-18', term: 'Exclusions and cessation of benefits', fact: 'Common exclusions: self-inflicted injury (sane or insane); alcohol/drug indulgence unless prescribed; war/riot; armed forces service (except peacetime reservist under Enlistment Act 1970); pregnancy/childbirth (unless disability persists more than 90 days after pregnancy termination, deemed to start 90 days after); aerial activity except fare-paying scheduled flights; STDs/HIV/AIDS; professional/hazardous sports; pre-existing conditions. Benefits cease when the insured is fit to return to work, dies, or the benefit period expires.', trap: 'Pregnancy-related disability only pays if it continues more than 90 days after pregnancy termination, deemed to begin at day 90.' },
      { id: 'h4-19', term: 'Group Disability Income Insurance', fact: 'Group Disability Income Insurance is bought by the employer as an employee benefit, on a stand-alone basis or as a rider. Insurers only issue it if the employer already has a Group Term Life Insurance policy with them (or issue it as a rider to that policy). Coverage, benefits and exclusions work the same as individual policies; some insurers issue only for white-collar occupations.', trap: 'A Group Term Life policy is a prerequisite for Group Disability Income Insurance.' },
      { id: 'h4-20', term: 'Disability income claims procedure', fact: 'The insured must notify the insurer within a specified period (e.g. 60 days) from the disability\'s commencement; failure may invalidate the claim unless the insured proves it was impossible and he tried his best. Documents include claim form, claimant\'s statement, Clinical Abstract form, physician\'s statement, NRIC/birth certificate, evidence of earnings (IR8A, 12 months\' payslips), medical certificates, lab results, police report (if accident), and MOM incident report (if workplace).', trap: 'Claim notification example is within 60 days of disability commencement (compare Medical Expense Insurance\'s 90 days).' },
    ],
  },
  {
    id: 'h5',
    num: 5,
    title: 'Long-Term Care Insurance',
    page: 86,
    concepts: [
      { id: 'h5-01', term: 'What is Long-Term Care (LTC) Insurance', fact: 'LTC Insurance meets the costs of care for a person who, because of accident, illness, frailty or a combination, cannot function independently and must depend on others for basic ADLs. It covers care generally excluded by other medical insurance and pays in addition to policies like MediShield Life, Hospital Income and Critical Illness Insurance.', trap: 'LTC pays in ADDITION to other health policies; it is not income protection or medical-expense reimbursement.' },
      { id: 'h5-02', term: 'Advantages of buying LTC young', fact: 'Two advantages of buying LTC while young and healthy: (1) it costs less because premiums rise considerably with age; and (2) there is less risk of being rejected for cover owing to existing disabilities or medical history.', trap: 'Both advantages hinge on youth: lower premium and lower rejection risk.' },
      { id: 'h5-03', term: 'Types of LTC policies', fact: 'Two types: Service-based policy pays a benefit when the insured uses a covered service (home/nursing care), via reimbursement of cost up to the covered amount OR a pre-agreed amount regardless of actual cost. Disability-based policy pays when the insured has advanced dementia (including Alzheimer\'s), significant ADL limitations, or loss of intellectual capacity needing continuous supervision.', trap: 'Service-based = tied to service use; Disability-based = tied to disability trigger regardless of service used.' },
      { id: 'h5-04', term: 'Graduated ADL payment', fact: 'Benefits are paid monthly once certified by an approved registered medical practitioner. Some insurers pay 100% of the LTC monthly benefit if the insured cannot perform at least the minimum number of ADLs; others pay on a graduated scale (e.g. 50% if unable to do two of six ADLs, 100% if unable to do four of six).', trap: 'Graduated payout example: 2 of 6 ADLs = 50%, 4 of 6 ADLs = 100%.' },
      { id: 'h5-05', term: 'The six Activities of Daily Living (ADLs)', fact: 'The six ADLs are: Washing (bathe/shower or wash by other means); Dressing (put on/remove and fasten garments and appliances); Feeding (feed oneself after food is prepared); Toileting (use the lavatory or manage bowel/bladder with protective undergarments or appliances); Mobility (move indoors room to room on level surfaces); Transferring (move from bed to upright chair/wheelchair and vice versa).', trap: 'Six ADLs: washing, dressing, feeding, toileting, mobility, transferring. Feeding is only after food is prepared.' },
      { id: 'h5-06', term: 'Failure to perform an ADL and advanced dementia', fact: 'Failure to perform an ADL means the insured cannot do the task even with assistive devices (wheelchair, crutches) on his own and always requires another person\'s assistance throughout the activity. Advanced dementia means deterioration/loss of intellectual capacity or abnormal behaviour from Alzheimer\'s or irreversible organic disorders (excluding neurosis and psychiatric illness), needing continual supervision; confirmed by clinical assessments/standardised tests.', trap: 'Advanced dementia must arise from an ORGANIC reason; neurosis and psychiatric illness are excluded.' },
      { id: 'h5-07', term: 'Deferred period and pre-existing conditions', fact: 'Besides ADL failure, most insurers require a deferred period of 90 days from the first day of continuous inability to perform ADLs before LTC benefits are payable, so short-term post-hospital dependence does not trigger claims. LTC does not pay for undisclosed pre-existing conditions; if disclosed, the insurer may accept at standard/sub-standard rates, add exclusions, or reject, based on severity.', trap: 'Standard LTC deferred period is 90 days. Guards against anti-selection on pre-existing conditions.' },
      { id: 'h5-08', term: 'Other benefits under LTC Insurance', fact: 'Insurers usually include a small death benefit (indicative S$5,000 up to six times the LTC monthly benefit; cover ceases on payment). Others may add: Extended Care Benefit (extra sum every three or five years); Rehabilitation Benefit (reduced benefit, e.g. 50%, on partial recovery); Dependant Care Benefit (a % of the severe disability benefit if the insured has a dependent child); and Waiver of Premium (after deferment once qualifying for the severe disability claim).', trap: 'LTC death benefit is small: S$5,000 up to six times the monthly benefit.' },
      { id: 'h5-09', term: 'Maximum benefit and benefit payment term', fact: 'LTC benefits depend on the chosen plan, e.g. between S$300 and S$5,000 per month, provided the insured cannot perform the specified number of ADLs and meets other conditions. Some insurers allow a chosen benefit payment term (e.g. 12 years of benefits); a shorter term is cheaper, and premiums are waived during the benefit payment period. Schemes like CareShield Life offer lifetime pay-outs while severely disabled.', trap: 'Indicative benefit range S$300-S$5,000/month; premiums are waived during the benefit payment period.' },
      { id: 'h5-10', term: 'ElderShield overview and pay-outs', fact: 'ElderShield is a long-term care insurance scheme for severe disability, especially in old age. Introduced in 2002 it paid S$300/month for up to five years (ESH300, 60 months); reviewed in 2007 to ESH400 paying S$400/month for up to six years (72 months). ElderShield is no longer open for new applications.', trap: 'ESH300 = S$300/month for 60 months; ESH400 = S$400/month for 72 months. ElderShield launched 2002, upgraded 2007.' },
      { id: 'h5-11', term: 'ElderShield premiums and Government administration', fact: 'ElderShield premiums are fixed at entry, based on the age of joining, and payable each year until the policy anniversary after the insured\'s 65th birthday or upon a successful claim. Coverage is for life once premiums are fully paid at 65. From 1 November 2021 the Government took over ElderShield administration from private insurers (Singlife, Great Eastern, Income Insurance).', trap: 'Premiums are payable until the policy anniversary after the 65th birthday; coverage is then lifetime. Government took over admin from 1 Nov 2021.' },
      { id: 'h5-12', term: 'ElderShield enrolment history', fact: 'Until 2019, all Singapore Citizens and SPRs with MediSave Accounts were auto-enrolled into ElderShield at age 40 unless they opted out. Since 2020, auto-enrolments into ElderShield stopped; those born 1980 and after were enrolled into CareShield Life at age 30. Those born 1970-1979 on ElderShield 400 without pre-existing disabilities were also enrolled into CareShield Life (could opt out by 31 December 2023).', trap: 'ElderShield auto-enrolment was at age 40; CareShield Life auto-enrolment is at age 30.' },
      { id: 'h5-13', term: 'ElderShield claim eligibility and assessment cost', fact: 'One can claim ElderShield if an MOH-accredited assessor determines the person is unable to perform three of the six ADLs. To claim, arrange a disability assessment by an MOH-accredited severe disability assessor; assessment costs S$100 for a clinic assessment and S$250 for a house call. The full fee is reimbursed (with the first pay-out) if assessed as severely disabled.', trap: 'ElderShield trigger is inability to do 3 of 6 ADLs. Assessment: S$100 clinic, S$250 house call.' },
      { id: 'h5-14', term: 'CareShield Life overview and compulsory scope', fact: 'CareShield Life launched on 1 October 2020 with enhanced benefits over ElderShield, supporting basic long-term care for Singaporeans with severe disability. It is compulsory for all Singaporeans born in 1980 or later: those born 1980-1989 were auto-enrolled in 2020, and those born 1990 onwards are auto-enrolled at age 30. Those with pre-existing disabilities/illnesses are still covered (universal coverage).', trap: 'CareShield Life launched 1 Oct 2020; compulsory for those born 1980 or later; covers pre-existing conditions.' },
      { id: 'h5-15', term: 'CareShield Life pay-outs and four assurances', fact: 'CareShield Life provides better protection four ways: (1) lifetime cash pay-outs for as long as the insured is severely disabled; (2) pay-out starting at S$600/month in 2020, increasing annually until age 67 or when a successful claim is made; (3) Government subsidies to keep premiums affordable; and (4) premiums fully payable by MediSave.', trap: 'CareShield Life starts at S$600/month in 2020 and increases until age 67 (or a successful claim). Pay-out is for the entire disability duration.' },
      { id: 'h5-16', term: 'CareShield Life for those born 1979 or earlier', fact: 'A person born 1979 or earlier is auto-enrolled into CareShield Life from 1 December 2021 if born 1970-1979, on ElderShield 400, and without severe disability; otherwise participation is optional and current ElderShield plans continue. They can join if they do not have severe disability, and enjoy participation incentives of up to S$3,000 if covered by 31 December 2024 (spread over 10 years to offset premiums).', trap: 'Participation incentive is up to S$3,000, spread over 10 years, for joining by 31 December 2024.' },
      { id: 'h5-17', term: 'CareShield Life vs ElderShield comparison', fact: 'ElderShield300: S$300/month for 60 months, no subsidies. ElderShield400: S$400/month for 72 months, subsidies depending on circumstances. CareShield Life: pay-outs start at S$600/month in 2020 and increase over time, paid for the entire duration of disability, with Government subsidies and incentives. All three are payable by MediSave and use the trigger of inability to perform 3 or more of the 6 ADLs.', trap: 'All three schemes share the same 3-of-6-ADL trigger; only CareShield Life pays for the entire disability duration.' },
      { id: 'h5-18', term: 'MediSave Care', fact: 'MediSave Care, launched 1 October 2020, lets Singapore Citizens and SPRs aged 30 and above with severe disability withdraw cash of up to S$200/month from their own and/or their spouse\'s MediSave for long-term care, after setting aside a minimum for other medical expenses. Withdrawal quantum scales with balance: S$20,000+ = S$200, S$15,000+ = S$150, S$10,000+ = S$100, S$5,000+ = S$50, below S$5,000 = not available. Eligibility needs an MOH-accredited assessment of inability to do 3 or more of 6 ADLs.', trap: 'MediSave Care max withdrawal is S$200/month, only if balance is S$20,000+. Below S$5,000 balance means no withdrawal.' },
      { id: 'h5-19', term: 'ElderFund and IDAPE', fact: 'ElderFund (launched 31 January 2020) is a discretionary scheme for lower-income Singapore Citizens aged 30+ with severe disability who are NOT eligible for CareShield Life, ElderShield or IDAPE, paying S$150 or S$250/month. IDAPE gives cash assistance of S$150 or S$250/month for up to 6 years to low-income Citizens who developed severe disability but could not join ElderShield in 2002 due to age or pre-existing disabilities.', trap: 'CareShield Life/ElderShield/Supplement policyholders are NOT eligible for ElderFund pay-outs.' },
      { id: 'h5-20', term: 'Other LTC financing schemes (PioneerDAS, SMF, HCG, MDW, CTG)', fact: 'PioneerDAS: S$100/month for life for moderately disabled Pioneers needing help with 3 of 6 ADLs. Seniors Mobility and Enabling Fund (SMF): means-tested subsidies for assistive devices/home healthcare items. Home Caregiving Grant (HCG): S$250 or S$400/month for care recipients needing help with 3 of 6 ADLs. MDW Levy Concession (PWD): lower levy of S$60/month for households hiring a domestic worker to care for someone needing help with at least 1 ADL. Caregivers Training Grant (CTG): annual subsidy of S$200 for approved caregiver courses.', trap: 'MDW levy concession needs only 1 ADL; PioneerDAS and HCG need 3 ADLs. CTG is S$200/year; PioneerDAS is S$100/month for life.' },
    ],
  },
  {
    id: 'h6',
    num: 6,
    title: 'Critical Illness Insurance',
    page: 100,
    concepts: [
      { id: 'h6-01', term: 'Critical Illness (Dread Disease) Insurance', fact: 'CI Insurance (also known as Dread Disease Insurance) pays a lump sum benefit when the insured is diagnosed with one of the critical illnesses, or undergoes a surgical procedure, covered under the policy. Each CI and surgery is defined in the policy and benefits are paid only if the condition meets the policy definition. It can be sold as a stand-alone policy (individual or group), or as an optional rider to a Whole Life, Endowment, Term or Investment-Linked Policy (ILP).', trap: 'The original product was called Dread Disease Insurance and covered only four conditions: Cancer, Stroke, Heart Attack and Coronary Artery Bypass.' },
      { id: 'h6-02', term: 'LIA CI Framework 2019 - 37 conditions', fact: 'Under the LIA Critical Illness Framework 2019, severe CI definitions are standardised for 37 medical conditions by way of common definitions. Since 2003 the industry standardised a list of 37 severe CIs; reviews were done in 2014 and 2019. LIA reviews the common definitions once every three years. An insurer covering a listed condition must adopt LIA\'s common definition for the severe stage, but uses its own definitions for the mildly-moderately severe stage or extremely severe stage.', trap: 'The number is 37 conditions (not 30 or 36). LIA defines only the SEVERE stage; insurers set their own definitions for other stages and for conditions not on the list.' },
      { id: 'h6-03', term: '26 August 2020 cut-off and waiting period update', fact: 'On and after 26 August 2020, CI products using Version 2014 definitions may not be sold; any CI policy purchased from 26 August 2020 is subject to the 2019 CI definitions. Policies issued before were not impacted. From 16 November 2022, insurers can independently determine suitable waiting periods, and the S$25,000 cap on sum payable for Angioplasty and Other Invasive Treatment for Coronary Artery was removed.', trap: 'The waiting period runs from the date cover commences or date of reinstatement, and the date of diagnosis is used to apply the waiting period.' },
      { id: 'h6-04', term: 'Eligibility criteria for CI benefit payment', fact: 'CI benefits are payable ONLY if: the policy is in force; the life insured has not reached the CI cover expiry age; the CI suffered is one covered under the policy and is the first incidence (not pre-existing/excluded); it meets the CI definition specified; it is diagnosed after the waiting period; and the life insured survives the survival period if one is imposed. Diagnosis must be by a registered medical practitioner (not the insured, spouse or lineal relatives) supported by medical evidence.', trap: 'Survival period applies ONLY to the Additional Benefit type of CI cover.' },
      { id: 'h6-05', term: 'Waiting period vs survival period', fact: 'The waiting period is the time from date of issue/reinstatement before which a diagnosed CI is not covered; it prevents anti-selection. If a person is found to suffer a CI before or during the waiting period, the insurer voids the policy and refunds premiums paid. The survival period is the time starting from the date of occurrence of a CI which the insured must survive before the benefit becomes payable.', trap: 'Waiting period targets timing of diagnosis relative to policy start; survival period requires the insured to stay alive for a set time after CI occurrence, and applies only to Additional Benefit cover.' },
      { id: 'h6-06', term: 'Major Cancer definition', fact: 'Major Cancer is a malignant tumour positively diagnosed with histological confirmation, characterised by uncontrolled growth of malignant cells with invasion and destruction of normal tissue. It includes leukaemia, lymphoma and sarcoma. Cancer diagnosed only from finding tumour cells/molecules in blood, saliva, faeces, urine or other bodily fluid without further definitive evidence does NOT meet the definition. Excluded are pre-malignant, non-invasive, carcinoma-in-situ (Tis/Ta), and various low-stage classifications.', trap: 'Suffering from cancer does not itself make a valid claim; the diagnosis must meet the exact severe-stage definition, so early/in-situ cancers are excluded from a traditional CI policy.' },
      { id: 'h6-07', term: 'Features of CI Insurance', fact: 'Common features: pays a lump sum on diagnosis of an insured CI; only one CI claim allowed unless it is a Multiple Pay plan; has a waiting period; may cap total coverage to minimise moral hazard; premium can be level or age-banded and is non-guaranteed; no restriction on use of benefit; can be standalone or a rider; provides 24-hour worldwide coverage unless endorsed. Minimum sum assured e.g. S$10,000 and maximum e.g. S$2,000,000; cover may expire at a maximum age (e.g. 75) or be whole life.', trap: 'A stand-alone Term CI policy and a CI rider do NOT acquire cash value (so no non-forfeiture option); only packaged CI on Whole Life/Endowment accumulates cash value.' },
      { id: 'h6-08', term: 'Acceleration Benefit CI cover', fact: 'Acceleration Benefit CI must be packaged into or attached to a basic policy (ILP, Term, Endowment or Whole Life). On CI diagnosis it pre-pays a portion (e.g. 50%) or the full (100%) basic sum assured. Example: a S$200,000 Whole Life CI policy with 50% acceleration pays S$100,000 on CI, with the balance S$100,000 plus bonuses paid on later death/TPD. Total amount paid always equals the basic sum assured plus bonuses. A 100% acceleration claim terminates the policy.', trap: 'With acceleration, the CI payout is taken OUT OF the basic sum assured; total paid never exceeds the basic sum assured plus bonuses. Contrast with Additional Benefit which pays ON TOP.' },
      { id: 'h6-09', term: 'Additional Benefit CI cover', fact: 'Additional Benefit CI is available stand-alone or as a rider. Stand-alone: sum assured paid on CI diagnosis and policy terminates. As a rider: it pays an amount IN ADDITION to the basic policy\'s sum assured. Example: a S$100,000 Whole Life policy with a S$200,000 Additional Benefit CI rider pays S$200,000 on CI, and the S$100,000 is still paid later on death/TPD (total S$300,000 if CI then death). As a rider the sum assured can be higher than the basic policy, e.g. up to five times.', trap: 'Additional Benefit rider payout does NOT affect the basic sum assured; the basic policy continues in force. The rider term must not exceed the basic policy and usually expires around age 65.' },
      { id: 'h6-10', term: 'Severity-Based CI (Early Pay CI)', fact: 'Severity-Based CI (Early Pay CI) pays at various stages of illness - early, intermediate to severe - giving a percentage of the sum assured per stage subject to a monetary cap per severity level. Progressive payments can total multiples of the original coverage. Advantages: greater number of illnesses covered (including less severe forms), payouts at an early stage, ability to claim more than once (including unrelated conditions), and continuity of cover after a less-severe claim. An early pay CI plan is MORE expensive than a severe CI plan.', trap: 'Unlike traditional all-or-nothing severe CI, severity-based pays a percentage based on severity. There is a maximum total claimable and each claim is deducted from the sum assured.' },
      { id: 'h6-11', term: 'Multiple Pay CI Insurance', fact: 'A multi-pay CI plan pays multiple times over each diagnosis of a CI and also for relapse or recurrence, subject to applicable waiting periods. A second and subsequent claim is allowed if the condition deteriorates or a different condition occurs. Multiple claims are not restricted to severe stage; if the plan includes severity-based CI, insurers may allow multi-claims on early stages subject to benefit limits. Future premiums may be waived upon first claim on advanced stage CI.', trap: 'Traditional/acceleration CI allows only ONE claim; only Multiple Pay plans allow more than one CI claim.' },
      { id: 'h6-12', term: 'CI plans covering mental illnesses and diabetes', fact: 'CI plans covering mental illness typically pay a lump sum (usually reduced coverage of the original CI) upon diagnosis, covering five conditions: Major Depressive Disorders (MDD), Schizophrenia, Bipolar Disorder, Obsessive Compulsive Disorder (OCD) and Tourette Syndrome. Payout is limited to a maximum benefit per life. Insurance covering diabetes provides a lump sum on diagnosis of the chronic illness, diabetes complications or a diabetes-related CI, and may extend to limb amputation(s). Waiting and survival periods may apply.', trap: 'Mental illness cover is limited to exactly five listed conditions and pays a reduced sum, not the full original CI amount.' },
      { id: 'h6-13', term: 'Adequacy of CI coverage', fact: 'Factors to determine adequacy of CI coverage: (1) minimum four years of income after taking into account debt - the net coverage should support the insured\'s standard of living for four years; (2) recovery expenses such as nurses and domestic help; and (3) providing for dependents - coverage should last until a young child is independent. Some early-stage plans covering recurring CI can pay out up to 600 per cent of the sum assured.', trap: 'The rule of thumb is CI coverage of at least four years of income; CI is a living benefit that complements (not replaces) life insurance, which pays only on death.' },
      { id: 'h6-14', term: 'CI exclusions', fact: 'Common CI exclusions: pre-existing illnesses; self-inflicted injury or illness (sane or insane); wilful misuse of drugs and/or alcohol; congenital anomalies or inherited disorders; AIDS or HIV infection; bodily injury from travel in/on aircraft except as a fare-paying passenger or crew of a scheduled licensed commercial flight; and war or warlike operation, nuclear, strike, riot and civil commotion risks.', trap: 'Exclusions vary from insurer to insurer; you must check the precise exclusions of your own insurer.' },
      { id: 'h6-15', term: 'Termination of CI cover and underwriting', fact: 'CI cover terminates on: a valid CI claim (usual case); the maximum coverage paid out; maturity/expiry of the basic policy; lapse for non-payment after grace period; surrender for cash value or conversion to Extended Term Insurance; death of the insured; or the insured reaching the CI rider expiry age. Underwriting is basically the same as for Life Insurance except the non-medical limit for CI is LOWER. Usually only standard and sub-standard risks up to a medium rating can be considered.', trap: 'The non-medical limit for CI is lower than for Life Insurance; risks with high extra mortality or declined for Life Insurance are not acceptable for CI.' },
      { id: 'h6-16', term: 'Group CI Insurance', fact: 'Group CI Insurance can be issued as a packaged policy or a rider and its coverage is similar to individual CI (Acceleration or Additional Benefit). However, there will ALWAYS be an expiry age (e.g. 75 years) specified regardless of whether it is Acceleration or Additional Benefit cover. Claims require a claimant\'s statement, an Attending Physician\'s Report and proof of the CI (biopsy/histology/imaging/laboratory reports).', trap: 'Group CI always has a stated expiry age even for the Additional Benefit type, unlike some individual whole-life CI arrangements.' },
    ],
  },
  {
    id: 'h7',
    num: 7,
    title: 'Other Types Of Health Insurance',
    page: 134,
    concepts: [
      { id: 'h7-01', term: 'Hospital Cash (Income) Insurance', fact: 'Hospital Cash (Hospital Income) Insurance pays a fixed daily cash benefit (e.g. S$200) if the insured is hospitalised due to injury or illness, independent of actual hospitalisation costs. Payment is limited to a specified number of days (e.g. 180 days) per hospitalisation per year, and some insurers impose a lifetime limit (e.g. 1,000 days). It is paid ON TOP of all other health insurance including MediShield Life, Integrated Shield Plans and Group H&S schemes.', trap: 'The benefit is a fixed dollar amount unrelated to actual cost, and is additional to (not offset by) any other medical insurance.' },
      { id: 'h7-02', term: 'Hospital Cash worked example (per-hospitalisation and lifetime caps)', fact: 'In the textbook example, Harry has a S$100/day benefit up to 180 days per hospitalisation and 1,000 days per lifetime. Stays of 210, 190 and 200 days were each paid only 180 days (the per-hospitalisation cap). His final 2023 stay of 160 days was paid only 140 days because his lifetime balance was 1,000 - 860 = 140. Total 1,000 days x S$100 = S$100,000, after which the policy was terminated.', trap: 'Both a per-hospitalisation cap AND a lifetime cap apply; reaching the lifetime limit terminates the policy.' },
      { id: 'h7-03', term: 'Hospital Cash waiting period and confinement', fact: 'For injury caused by an accident directly and independently of any other cause, there is NO waiting period. For illness, hospitalisation must be for an illness contracted/commenced after policy issuance or reinstatement for a specified period, and not a specifically excluded illness. The insured must be confined to a hospital for a specified minimum number of hours. Owing to small premiums, Hospital Cash is not underwritten; a waiting period applies and pre-existing conditions are permanently excluded.', trap: 'No waiting period for injury; a waiting period applies for illness. Pre-existing conditions are permanently excluded.' },
      { id: 'h7-04', term: 'Stand-alone Hospital Cash enhancements', fact: 'Stand-alone Hospital Cash offers more attractive benefits: more than 100% of daily benefit for HDU/CCU stays; double or triple payment for ICU stays; triple payment if hospitalisation is due to accident or overseas; get-well benefit; rehabilitation income; free accidental death benefit; and involuntary loss of employment benefit (in excess of 30 days) waiver of premium up to six months. Premiums increase by age-band on renewal.', trap: 'Enhanced multiples (double/triple) are features of stand-alone plans; the daily benefit itself is otherwise fixed and premiums rise with age-band.' },
      { id: 'h7-05', term: 'Hospital Cash termination and claims', fact: 'Hospital Cash cover terminates when: premium is unpaid at end of grace period; the insured reaches the stated expiry age; the per-lifetime limit is reached; the basic policy lapses or matures; or the insured dies. A claim requires a claim form plus the hospital discharge summary and bills; the insurer may request an Attending Physician\'s Report and other documents.', trap: 'The cover typically expires at a specified age such as 65, 70 or 75 years and renews yearly.' },
      { id: 'h7-06', term: 'Maternity Insurance', fact: 'Maternity Insurance covers mother and baby during pregnancy, and may cover up to the end of the 3rd policy year, protecting against complications of pregnancy and birth. It does NOT cover the usual cost of giving birth where no complications arise. Mother benefits: medical expenses for covered complications, death or TPD benefit, hospitalisation income. Newborn benefits: medical expenses for congenital illnesses, death benefit, hospitalisation income, outpatient cash for phototherapy machine; may cover up to four babies in a single pregnancy.', trap: 'Costs of delivery, including pre- and post-hospitalisation bills, are excluded; normal (complication-free) childbirth is not covered.' },
      { id: 'h7-07', term: 'Maternity Insurance features', fact: 'Maternity Insurance is a single-premium term policy, valid for three years from the policy start date, protecting mother and child (up to three babies in a single pregnancy in the features list) from as early as the 13th week of pregnancy. It has no cash value, allows no assignment, and the insurer may offer an option to buy a regular-premium whole life/endowment/ILP for the mother or child within 90 days of the child\'s birth without medical underwriting.', trap: 'The benefits section mentions up to four babies covered, while the features list states protection for up to three babies in a single pregnancy (and excludes carrying three or more babies as an exclusion). Coverage starts from the 13th week.' },
      { id: 'h7-08', term: 'Travel Insurance medical benefits', fact: 'Medical benefits under Travel Insurance usually include: medical expenses and other related benefits; hospital confinement allowance; emergency medical evacuation; and repatriation. It reimburses non-elective overseas medical/treatment expenses (clinical, hospital, surgical, nursing, ambulance, emergency dental, miscarriage) plus follow-up in Singapore within a specified period, and TCM treatment up to a limit. There is no age limit to apply, so insurers set lower limits for children (below 18) and higher limits for seniors (usually above 70).', trap: 'Pre-existing conditions are excluded unless the insured opts in (with extra premium and/or simple health questions).' },
      { id: 'h7-09', term: 'Emergency medical evacuation and repatriation', fact: 'Emergency medical evacuation covers evacuation to another place for emergency treatment when local medical services are inadequate/unavailable; the insured must contact the insurer\'s contracted specialist company (24-hour multilingual hotline) which decides on evacuation. Repatriation covers emergency medical repatriation (return to country of origin) and repatriation of body remains. For both, the lower coverage plan has a maximum benefit limit while the higher coverage plan is usually unlimited.', trap: 'Evacuation/repatriation decisions rest with the attending doctor or the insurer\'s contracted specialist company, not the insured.' },
      { id: 'h7-10', term: 'Group Dental Care Insurance', fact: 'Group Dental Care Insurance is offered without underwriting and issued as a RIDER to a Group Hospital and Surgical Insurance policy. Only actively-at-work employees are covered, usually non-contributory, 24-hour worldwide, usually issued for two years then renewable every one or two years. Benefits range from scaling and polishing to root canal and wisdom tooth extraction, per a Schedule of Allowances with panel and non-panel limits, or some insurers set an overall annual claim limit per employee.', trap: 'Group Dental is a rider to a Group H&S policy, not a stand-alone policy, and requires no underwriting.' },
      { id: 'h7-11', term: 'Group Dental exclusions, limitation clause, termination', fact: 'Common Group Dental exclusions: procedures not in the Schedule of Allowances; hospital charges; war-related injuries; medicine given; purely cosmetic treatment; treatment from self-inflicted injury; and replacement of broken/lost/stolen dentures. The Limitation Clause reduces reimbursements by benefits claimable under Work Injury Compensation Insurance, any government/public dental or medical programme, or any other group/individual Health or Dental policy. Cover terminates on end of employment, policy termination, last-premium expiry, entering full-time military service (except peacetime NS), or reaching a specified age (e.g. 65).', trap: 'The Limitation Clause co-ordinates benefits and prevents double recovery; it reduces payouts by amounts claimable elsewhere.' },
    ],
  },
  {
    id: 'h8',
    num: 8,
    title: 'Managed Healthcare',
    page: 152,
    concepts: [
      { id: 'h8-01', term: 'Managed Healthcare (MHC)', fact: 'MHC is an overall strategy for containing medical care costs while assuring that people receive appropriate medical care; it pays for most medical bills when a person sees a GP, specialist or is treated in hospital. MHC schemes evolved in response to rising medical costs and are usually run by insurers as insurance-backed plans. Locally, only GROUP MHC insurance is available, often bought by employers as part of an Employee Benefit package and as an alternative to Group H&S plans.', trap: 'In Singapore only GROUP MHC insurance is available; individual MHC is not.' },
      { id: 'h8-02', term: 'Three components managed by MHC', fact: 'MHC contains and controls healthcare expenditure by managing three components: (a) accessibility; (b) cost; and (c) quality of care. Providers set up a healthcare network and negotiate contracts with doctors, hospitals, clinics, pharmacies, labs, X-ray centres and equipment vendors in exchange for directing more patients to them.', trap: 'The three managed components are accessibility, cost and quality of care.' },
      { id: 'h8-03', term: 'Primary Care Physician (PCP) as gatekeeper', fact: 'In an MHC plan members are referred to a selected network; a member may need all services from a Primary Care Physician (PCP), usually a general practitioner, who is the first contact and the member\'s personal physician. Under most MHC plans a member must obtain a referral from the PCP before seeing a specialist, so PCPs are called gatekeepers. Members are allowed to change their PCPs.', trap: 'The PCP acts as a gatekeeper controlling access to specialists; going outside the network usually means paying a larger share of the cost.' },
      { id: 'h8-04', term: 'Four MHC payment methods', fact: 'The four common payment methods used by MHCOs are: (a) Capitation - a fixed pre-paid amount per member (usually monthly) regardless of usage; (b) Discounted-Fee-For-Service - pays a percentage of normal fees (e.g. 90%, a 10% discount); (c) Salary - used in the Staff Model HMO, physicians paid a fixed salary based on average local earnings plus performance bonuses; and (d) Fee Schedule - caps the dollar amounts reimbursed per procedure. Other cost controls include Utilisation Management and risk-sharing agreements.', trap: 'Capitation = fixed prepaid amount per member regardless of usage; Fee Schedule = per-procedure maximum caps. Do not confuse the two. Fee Schedule can encourage unnecessary services.' },
      { id: 'h8-05', term: 'Health Maintenance Organisation (HMO)', fact: 'An HMO features a network of providers that treat a patient population for a prepaid fee. The member must receive most or all care from a network provider and must choose a PCP who manages and coordinates all care; a referral from the PCP is needed for specialists, labs or X-rays. Without a referral or when going out-of-network, the member usually pays all or most costs unless pre-authorised or an emergency. The HMO is the MOST restrictive type of health plan (least choice of provider).', trap: 'HMO = greatest cost control but lowest choice of provider; always see the PCP first.' },
      { id: 'h8-06', term: 'Preferred Provider Organisation (PPO)', fact: 'A PPO has negotiated contracts with a network of preferred providers. A member does NOT need to select a PCP and does NOT need referrals to see other network providers. It offers richer benefits (lower/no deductible, lower/no co-payment, higher benefits) as financial incentives to use network providers; seeing a non-network provider may cost as much as 50% of the total bill. PPOs are LESS restrictive than HMOs but tend to require greater out-of-pocket payments.', trap: 'With a PPO you can see a specialist without a referral, unlike an HMO.' },
      { id: 'h8-07', term: 'Point-of-Service (POS) plan', fact: 'A POS plan is a combination of an HMO and a PPO. Like an HMO, it requires choosing an in-network PCP and getting referrals for specialists to be covered. Like a PPO, it still covers out-of-network services, but the policyholder pays more for those than for in-network. At each point of service the member decides whether to stay in-network (PCP manages care) or go outside the network without a referral.', trap: 'POS is the hybrid: HMO-style referral requirement combined with PPO-style out-of-network coverage at higher cost.' },
      { id: 'h8-08', term: 'Choice of providers vs cost control', fact: 'There is a trade-off between choice of providers and cost control. The HMO has the GREATEST cost control but the LOWEST choice of providers; savings are passed to purchasers as lower prices. Traditional Medical Expense Insurance has NO cost control and NO access restriction, so its premium is higher. Ordered by decreasing cost control / increasing provider choice: HMO, POS, PPO, then Traditional Medical Expense Insurance. No plan can offer high benefits, unlimited access and low cost all at once - only two of the three.', trap: 'You can only achieve two of the three: high benefits, unlimited access, low cost.' },
      { id: 'h8-09', term: 'MHC Insurance benefits, co-payments and claims', fact: 'MHC Insurance for fixed annual premiums may provide: Primary Care (GP network), Specialist Care (on PCP referral), Hospital Care (subject to limits), Emergency Care (24-hour) and Preventive Care (educational programmes). Co-payments such as co-insurance, deductible and pro-ration factors may apply, as in Medical Expense Insurance. For claims, in-network members do not file claims (settled between MHCO and providers); only out-of-network members file claims, submitting the claimant\'s statement and original itemised medical bill.', trap: 'In-network care requires no claim filing by the member; only out-of-network use requires a claim submission.' },
      { id: 'h8-10', term: 'MHC model in Singapore', fact: 'MHC arrangements are not common in Singapore. Employers engage an MHCO or insurer to offer cashless outpatient GP and specialist consultations; the GP acts as gatekeeper and a referral is needed to see a specialist with cost covered. Employees must use the selected panel for cashless facilities; visiting a non-panel clinic means the cost is not covered or only partially covered subject to co-payments/benefit limits. Under an insured scheme, the insurer may add a Group H&S hospitalisation cover, potentially cashless via a letter of guarantee.', trap: 'Non-panel visits are only partially or not covered; the GP gatekeeper role minimises unnecessary specialist visits.' },
    ],
  },
  {
    id: 'h9',
    num: 9,
    title: 'Healthcare Financing',
    page: 161,
    concepts: [
      { id: 'h9-01', term: 'Healthcare subsidies and means-testing', fact: 'The Government funds public healthcare institutions and selected private clinics/VWOs so Singaporeans access subsidised care. A means-test targets subsidies so lower-income patients receive more. Class B2 and C ward admissions (81% of public hospital beds) are heavily subsidised, ranging from 50% to 80% for Singapore Citizens and 25% to 50% for Permanent Residents. Class B1 or Class A patients receive little to no subsidy. Means-testing in public hospitals was introduced in January 2009, based on Per Capita Household Income or Annual Value of Residence (for households with no income).', trap: 'Class C/B2 = heavily subsidised (50-80% SC); Class A/B1 = little to no subsidy. Means-testing since Jan 2009.' },
      { id: 'h9-02', term: 'Subsidy tiers by service', fact: 'SOC services: subsidies range from 30% to 70% by PCHI and Annual Value; PRs receive 25%. Standard drugs at SOCs: 50% or 75% means-tested. Day surgery: subsidised up to 80% (50-80% for SCs, 25-50% for PRs); A&E subsidised up to 50% (flat rate charged). Government polyclinics: subsidised about 50% (75% for a child or elderly person); lower- to middle-income get 75% subsidy for all standard drugs. Intermediate long-term care providers: MOH subsidies of up to 80%.', trap: 'Different service tiers: SOC 30-70%, day surgery up to 80%, A&E up to 50%, polyclinics about 50% (75% for child/elderly).' },
      { id: 'h9-03', term: 'Community Health Assist Scheme (CHAS)', fact: 'CHAS enables eligible Singapore Citizens to receive subsidies for medical and/or dental care at participating GP and dental clinics. With effect from November 2019 it was expanded to include ALL Singapore Citizens regardless of income. Card colours indicate the subsidy tier: CHAS Blue, Orange or Green. All Pioneer Generation (PG) and Merdeka Generation (MG) seniors also receive special subsidies at CHAS clinics. CHAS complements the Chronic Disease Management Programme (CDMP), where MediSave can be used for outpatient treatment.', trap: 'Since Nov 2019 CHAS covers all Singapore Citizens; the card colour (Blue/Orange/Green) shows the subsidy tier.' },
      { id: 'h9-04', term: 'MediShield Life overview', fact: 'MediShield Life is a basic health insurance scheme protecting all Singapore Citizens (SCs) and Permanent Residents (PRs) against large medical bills for life, regardless of age or health condition, by risk-pooling across the whole population. Claim limits are designed to cover 9 in 10 subsidised bills for Class B2/C ward hospitalisation, day surgeries and selected costly outpatient treatments (e.g. dialysis, cancer drug treatments). No application is needed; all SCs and PRs were automatically enrolled from 1 November 2015. New SCs are covered from birth or citizenship; PRs from attaining PR.', trap: 'MediShield Life is sized for Class B2/C wards; those wanting Class A/B1 or private cover need an Integrated Shield Plan.' },
      { id: 'h9-05', term: 'MediShield Life premiums and Additional Premiums', fact: 'MediShield Life premiums are actuarially priced by age group so each age group\'s payouts are broadly supported by its own premiums. Those with pre-existing conditions are covered, but only those with SERIOUS pre-existing conditions listed by MOH pay Additional Premiums of 30% for the first 10 years of coverage, on top of standard premiums. Premiums can be fully paid by MediSave (own or family members\'), and parents may use the MediSave Grant for Newborns for a child\'s premiums.', trap: 'Additional Premiums are 30% for the first 10 years, and only for SERIOUS pre-existing conditions listed by MOH.' },
      { id: 'h9-06', term: 'MediShield Life premium subsidies (lower-middle income, PG, MG)', fact: 'Premium Subsidies for lower- to middle-income: household monthly income per person of S$2,800 and below and home Annual Value of S$21,000 and below (not owning more than one property); up to 50% of premiums (PRs receive half the SC subsidy). Pioneer Generation Subsidies: 40%-60% by age regardless of income/AV, plus MediSave top-ups of S$250-S$900 a year for life (plus S$50-S$200 annually 2021-2025 for older PG with serious pre-existing conditions). Merdeka Generation Subsidies (from 1 July 2019): 5% of annual premiums, rising to 10% after age 75, regardless of income/AV; MG members got S$200/year MediSave top-ups for five years 2019-2023.', trap: 'PG subsidies are 40-60%; MG subsidies are 5% rising to 10% after 75. Income-based subsidy is up to 50% of premiums.' },
      { id: 'h9-07', term: 'Additional Premium Support (APS)', fact: 'Individuals unable to afford MediShield Life premiums after Government subsidies, MediSave usage and with limited family support can be invited to apply for Additional Premium Support (APS). If approved, APS covers outstanding premiums plus the next two years\' premiums, and covers CareShield Life premiums if the applicant is covered under CSHL. No one loses MediShield Life coverage for inability to pay. However, individuals LOSE APS if they purchase an Integrated Shield Plan or an ElderShield/CSHL Supplement.', trap: 'Buying an IP or an ElderShield/CareShield Life Supplement disqualifies you from APS.' },
      { id: 'h9-08', term: 'MediShield Life claim computation - deductible, co-insurance, pro-ration', fact: 'MediShield Life pays on a reimbursement basis subject to claim limits, deductible, co-insurance and pro-ration. The deductible is a fixed amount payable each policy year before payouts start, payable only once per policy year, filtering out smaller bills. Co-insurance is the patient\'s share of the claimable amount, decreasing from 10% to 3% as the bill size increases. Class A/B1 and private bills are pro-rated down to the equivalent Class B2/C level before payouts are computed, to ensure comparable payouts for subsidised and private patients.', trap: 'Pro-ration reduces higher-ward bills to the B2/C equivalent BEFORE claim limits, deductible and co-insurance are applied.' },
      { id: 'h9-09', term: 'MediShield Life claim limits (Appendix 9B, updated April 2024)', fact: 'Daily Ward and Treatment Charges limits: Normal Ward S$800/day; ICU S$2,200/day (an additional S$200/day for the first two inpatient days); Psychiatric S$160/day (up to 60 days/policy year); Community Hospital Rehabilitative S$350/day, Sub-acute S$430/day; Inpatient Palliative Care General S$460/day, Specialised S$500/day. Implants S$7,000 per treatment. Surgical Procedures by table range from S$240 (Table 1A) up to S$2,600 (Table 7). Maximum Claim Limit: S$150,000 per policy year, with NO lifetime limit.', trap: 'The per-policy-year maximum is S$150,000 with no lifetime limit. Normal ward limit is S$800/day (Appendix 9B), though the older worked example in Table 9.2 uses S$700/day.' },
      { id: 'h9-10', term: 'MediShield Life deductible and co-insurance figures', fact: 'Deductible (based on age next birthday at start of policy year, for admissions on/after 1 March 2021): Class C S$1,500 (age 80 and below) / S$2,000 (81 and above); Class B2 and above including private hospital S$2,000 / S$3,000; Day Surgery S$1,500 / S$2,000; Outpatient not applicable. Co-insurance for Inpatient/Day Surgery by claimable amount accumulated per policy year: first S$5,000 (inclusive of deductible) at 10%, next S$5,000 at 5%, above S$10,000 at 3%. Outpatient co-insurance is 10%.', trap: 'Co-insurance tiers are 10% / 5% / 3% (first S$5,000 / next S$5,000 / above S$10,000). The first S$5,000 band is inclusive of the deductible.' },
      { id: 'h9-11', term: 'MediShield Life exclusions', fact: 'Not covered by MediShield Life (admissions on/after 1 March 2021): contraceptive/infertility/sub-fertility/assisted conception or sex re-assignment surgery; surgery for Trisomy 13, Bilateral Renal Agenesis, Bart\'s Hydrops and Anencephaly; cosmetic surgery; dental (except accidental injury); outright purchase of dialysis machines/iron-lung; optional items (TV, telephone, special meals); private nursing; ambulance; vaccination; treatment from own criminal act; nuclear/war risks; civil commotion/riot/strike; expenses after the 7th calendar day from being certified fit for discharge; overseas treatment; treatment reimbursed by Workmen\'s Compensation/other insurance; and maternity/abortion charges except serious pregnancy/childbirth complications.', trap: 'MediShield Life does NOT cover overseas treatment, vaccination, ambulance, or expenses after the 7th day from being certified fit for discharge.' },
      { id: 'h9-12', term: 'MediShield Life Fund', fact: 'MediShield Life is a non-profit scheme. All premiums collected go into the MediShield Life Fund, used solely for the benefit of policyholders and administration of the scheme. The Fund\'s financial accounts are audited by an external auditor and submitted to Parliament every year.', trap: 'The Fund is non-profit and its audited accounts are submitted to Parliament annually.' },
      { id: 'h9-13', term: 'Integrated Shield Plans (IPs)', fact: 'IPs are MediSave-approved hospitalisation insurance plans made up of two parts: the MediShield Life component administered by the CPF Board, and an additional private insurance component by approved private insurers (typically covering Class A/B1 public wards or private hospitals). Since MediShield Life implementation on 1 November 2015, it automatically replaced the MediShield component, so there is no duplication. IPs (as at 1 Apr 2023): AIA HealthShield Gold Max, Singlife Shield, HSBC Life Shield, Great Eastern SupremeHealth, Income\'s Enhanced IncomeShield, Prudential\'s PRUShield, and RHI\'s Raffles Shield.', trap: 'An IP holder is already covered by MediShield Life within the IP - one premium, one claim through the private insurer, no duplication.' },
      { id: 'h9-14', term: 'Integrated structure and coverage of IPs', fact: 'Under the integrated structure, an SC/PR with an IP enjoys MediShield Life benefits within the IP but is serviced by the private insurer - paying one premium and making one claim; the insurer arranges the MediShield Life portion with the CPF Board. The insured has lifelong coverage and coverage for pre-existing conditions under the MediShield Life component, even if the condition is excluded from the private insurance component. IP premiums comprise the MediShield Life component premium plus the additional private insurance component.', trap: 'The MediShield Life component still covers pre-existing conditions and gives lifelong coverage even if the private component excludes that condition.' },
      { id: 'h9-15', term: 'MediShield Life vs IP differences', fact: 'MediShield Life is administered by the CPF Board, sized for Class B2/C wards, covers all pre-existing conditions, has no min/max age limit, has sub-limits, is fully payable by MediSave, and covers all SCs/PRs automatically for life. An IP is administered by private insurers (MOH-approved), gives enhanced coverage for private hospitals and/or Class A/B1 wards, may decline/exclude/loading for pre-existing conditions, may have min/max entry age, mostly has no sub-limits, has the MediShield Life component fully payable by MediSave while the private component is payable by MediSave only up to the Additional Withdrawal Limit (AWL) with remainder in cash, and requires application.', trap: 'MediShield Life has sub-limits and no age limit; IPs mostly have no sub-limits but may impose entry-age limits and pre-existing exclusions/loading.' },
      { id: 'h9-16', term: 'Standard IP', fact: 'The Standard IP is a no-frills product covering large Class B1 ward bills and selected outpatient treatments. From 1 May 2016 all IP insurers were required to sell it. Its benefits are regulated by MOH and identical across all IP insurers, with claim limits sized to fully cover nine out of ten Class B1 bills, and it has co-insurance and deductible components. Premiums and underwriting are still set by each insurer, so premiums vary.', trap: 'The Standard IP targets Class B1 (not B2/C), its benefits are identical across insurers, but premiums still differ by insurer.' },
      { id: 'h9-17', term: 'MediSave use for IP premiums - Additional Withdrawal Limit (AWL)', fact: 'The MediShield Life component of IP premiums is fully payable by MediSave. From 1 November 2015, MediSave use for the additional private insurance component is subject to the Additional Withdrawal Limit (AWL), per insured person per policy year by Age Next Birthday (ANB): 40 years and below S$300; 41 to 70 years S$600; 71 years and above S$900. Excess premiums above the AWL are payable in cash.', trap: 'AWL for IPs: S$300 (ANB up to 40) / S$600 (41-70) / S$900 (71+). The private component beyond the AWL must be paid in cash.' },
      { id: 'h9-18', term: 'IP riders and 5% co-payment', fact: 'IP riders pay the co-insurance and deductible portion of the IP, subject to a minimum 5% co-payment. Riders are NOT approved for MediSave use and cannot be marketed as part of IPs (can be paid with cash only). From 8 March 2018, new IP riders must have a co-payment of 5% or more, and a co-payment cap for panel/pre-authorised treatment (insurers can set the cap at S$3,000 or more per policy year). New 5% co-payment riders applied from 1 April 2019; riders sold 8 March 2018 to 31 March 2019 had to transition by 1 April 2021.', trap: 'New IP riders require a minimum 5% co-payment; full riders that covered the entire co-payment are no longer allowed as they encouraged over-consumption. Riders are cash-only (not MediSave-approved).' },
      { id: 'h9-19', term: 'Terminating or switching IP / switching insurer', fact: 'An IP holder can switch to a lower-coverage plan within the same insurer any time without extra underwriting, or terminate the IP any time and still be covered by MediShield Life regardless of pre-existing conditions. Switching to a new insurer automatically terminates the original IP and requires new underwriting, risking loss of coverage for existing conditions. A policyholder who switches insurer can return to the previous insurer within 30 days of the termination notification with no re-underwriting, as if the first IP was never terminated.', trap: 'Switching insurers triggers new underwriting (risking loss of existing-condition cover); there is a 30-day window to revert to the previous insurer with no re-underwriting.' },
      { id: 'h9-20', term: 'Pre-authorisation for IP', fact: 'Pre-authorisation is a service where the IP insurer gives prior approval to hospitalisation/treatment and associated costs before surgery or admission. It is designed for elective treatments in the private healthcare sector for patients seeking private specialist care in private hospitals. Benefits: insurers can assess medical necessity and cost; patients gain peace of mind; providers have clarity on covered procedures. All IP insurers offering pre-authorisation must use the standard LIA Pre-Authorisation Form, and will directly settle pre-authorised bills with the hospital/day surgery centre/clinic.', trap: 'Pre-authorisation is for elective private-sector treatment and uses a standardised LIA form; a Letter of Guarantee is not the same as pre-authorisation.' },
      { id: 'h9-21', term: 'MediSave - the national health savings scheme', fact: 'MediSave is a mandatory national health savings scheme under the CPF, introduced on 1 April 1984. Between 8% and 10.5% of each employed CPF member\'s monthly salary (depending on age, from member and employer) goes to the MediSave Account (MA). Self-employed persons make compulsory contributions of between 4% and 10.5% of yearly income based on age and Net Trade Income after a Notice of Computation from IRAS. The MediSave Grant for Newborns makes each Singaporean baby a CPF member at birth and covers MediShield Life premiums from birth to age 21.', trap: 'Employed contribution 8%-10.5%; self-employed 4%-10.5%. MediSave started 1 April 1984.' },
      { id: 'h9-22', term: 'Basic Healthcare Sum (BHS)', fact: 'Contributions to the MA are capped at the Basic Healthcare Sum (BHS), designed to be enough for basic subsidised healthcare in old age. Amounts above the BHS flow to the Special or Retirement Account (or Ordinary Account if the Full Retirement Sum is met, withdrawable as cash from age 55). The BHS is adjusted yearly in January but only for members aged 65 and below that year; once a member reaches age 65 the BHS is fixed for the rest of his life. From 1 January 2022, the maximum top-up is the difference between BHS and current MA balance. Annual tax relief of up to S$8,000 (own SA/RA/MA) plus up to S$8,000 (loved ones\').', trap: 'The BHS is FIXED once the member turns 65 and never changes thereafter; yearly adjustments apply only to those 65 and below.' },
      { id: 'h9-23', term: 'MediSave uses - outpatient (MediSave500/700, Flexi-MediSave)', fact: 'MediSave can pay outpatient treatment for 23 approved chronic conditions under the Chronic Disease Management Programme (CDMP): up to S$500 for non-complex or S$700 for complex chronic conditions per patient per year (MediSave500/700). MediSave500/700 also covers approved vaccinations (NCIS/NAIS) and approved health screenings (e.g. mammograms for women 50+, newborn screening). Flexi-MediSave lets patients aged 60 and above use up to S$300 per patient per year (own or spouse\'s MA if spouse is also 60+) for outpatient treatment, vaccinations and screenings, usable together with MediSave500/700.', trap: 'CDMP covers 23 approved chronic conditions; MediSave500/700 = S$500 non-complex, S$700 complex. Flexi-MediSave = up to S$300/year for age 60+.' },
      { id: 'h9-24', term: 'MediSave uses - inpatient limits', fact: 'Inpatient daily hospital limit (admitted at least 8 hours): up to S$550 per day for the first two days and S$400 per day thereafter, covering ward charges, treatment fees, investigations and medicines. Surgical procedures: withdrawal limit S$250 to S$7,550 depending on complexity. Inpatient psychiatric: up to S$150 per day, maximum S$5,000 a year. Day surgery: up to S$300 per day. If a member dies during hospitalisation, his own MediSave can pay the last inpatient bill in full without withdrawal limits.', trap: 'Inpatient daily limit is S$550/day first two days then S$400/day; surgical range is S$250 to S$7,550. Day surgery daily limit is S$300.' },
      { id: 'h9-25', term: 'MediSave uses - long-term care and Assisted Conception', fact: 'Rehabilitation: community hospital S$250/day up to S$5,000 p.a.; convalescent hospital S$50/day up to S$3,000 p.a.; day hospital S$150/day up to S$3,000 p.a.; day rehabilitation centre (outpatient) S$25 per service per day up to S$1,500 p.a. Palliative care: inpatient hospice general up to S$250/day, specialised up to S$350/day; home palliative and day hospice up to S$2,500 per lifetime (no limit for terminal cancer/end-stage organ failure/advanced dementia paid from own MediSave). Disability care (MediSave Care): residents aged 30+ with severe disability withdraw up to S$200/month cash from own or spouse\'s MA. Assisted Conception Procedure limits: 1st cycle S$6,000, 2nd S$5,000, 3rd and subsequent S$4,000 (lifetime cap S$15,000 per patient).', trap: 'MediSave Care is for age 30+ with severe disability (up to S$200/month cash); ACP limits step down S$6,000 / S$5,000 / S$4,000 with a S$15,000 lifetime cap.' },
      { id: 'h9-26', term: 'MediSave for insurance premiums and approved dependants', fact: 'MediSave can pay the member\'s own or approved dependants\' healthcare expenses. Approved dependants are spouse, children, parents, siblings and grandparents (for a sibling/grandparent the patient must be an SC or SPR). MediShield Life and ElderShield/CareShield Life premiums are FULLY payable by MediSave, whereas IPs and ElderShield/CareShield Life supplements are subject to withdrawal limits reviewed by MOH. The AWL for ElderShield or CareShield Life Supplements is S$600 per calendar year per insured person.', trap: 'MediShield Life and ElderShield/CareShield Life = fully MediSave-payable; IPs and supplements = subject to withdrawal limits (Supplement AWL S$600/year).' },
      { id: 'h9-27', term: 'Claiming and MOH claims protocol (Last Payer)', fact: 'For IP claims the hospital submits electronically; the IP insurer computes the IP payout and the CPF Board independently computes the MediShield Life payout, and the eventual payout is the HIGHER of the two. To avoid duplicative payouts the MOH claims protocol pays in this order: (a) employer/private insurance/other third party first; (b) then MediShield Life/IP; (c) then MediSave; (d) then Cash. A Letter of Guarantee (LOG) waives upfront cash up to an eligible amount but does not guarantee the insurer will pay - pre-authorisation gives that assurance.', trap: 'IP payout = higher of IP benefits vs MediShield Life benefits. Claims order: third party/employer, then MediShield Life/IP, then MediSave, then cash.' },
      { id: 'h9-28', term: 'ElderShield - scheme basics', fact: 'ElderShield is a long-term care insurance scheme launched September 2002, providing basic financial protection for those needing long-term care in old age. Unlike compulsory MediShield Life, ElderShield is an OPT-OUT scheme. There are two schemes: ElderShield300 (launched 30 Sept 2002, S$300/month for up to 60 months) and ElderShield400 (introduced 2007, S$400/month for up to 72 months). Those joining after 30 September 2007 are on ElderShield400. Premiums are fully payable by MediSave. It became a CLOSED scheme from 1 August 2021, and the Government took over administration from 1 November 2021.', trap: 'ElderShield300 = S$300 x 60 months; ElderShield400 = S$400 x 72 months. Opt-out (not compulsory). Closed from 1 Aug 2021.' },
      { id: 'h9-29', term: 'ElderShield eligibility - ADLs, waiting and deferment periods', fact: 'ElderShield pays if the insured is unable to perform at least three of the six Activities of Daily Living (ADLs): Washing, Dressing, Feeding, Toileting, Mobility and Transferring. Waiting period: 90 days from commencement (no benefit if disabled in first 90 days; instead policy is terminated and premiums refunded), but waived if disability is solely due to an accident, and waived for auto-enrolled policyholders. Deferment period: 90 days from the claim date (date claim received by the AIC); benefit is payable if still disabled after this period. The deferment period does not apply to a relapse from the same cause within 180 days of recovery if the first disability lasted at least 90 days.', trap: 'Must fail at least 3 of 6 ADLs. Waiting period (90 days from start) vs deferment period (90 days from claim date) are distinct; the accident exception waives only the waiting period.' },
      { id: 'h9-30', term: 'ElderShield claims, payout and non-forfeiture', fact: 'To claim, the insured is assessed by an MOH-accredited severe disability assessor who submits the form to the Agency for Integrated Care (AIC). Assessment costs S$100 at the assessor\'s clinic or S$250 for a house call, reimbursed by AIC if the outcome is severe disability. Benefits are paid monthly and premiums are waived during payout; on recovery, payout stops and premiums resume, and the insured can claim again later up to the 60/72-month total. The cash payout is not tied to institutional care. ElderShield is pre-funded, so it can acquire a reserve and be converted to a paid-up policy (reduced benefits) if premiums stop after some years.', trap: 'Assessment fee S$100 clinic / S$250 house call, reimbursed only if severe disability is confirmed. ElderShield payout is not tied to institutional care.' },
      { id: 'h9-31', term: 'ElderShield features, exclusions, termination', fact: 'ElderShield features: guaranteed renewable annually; worldwide coverage; minimum entry age 40, maximum entry age 64; grace period of 75 days; reinstatement allowed within 180 days of grace-period expiry (with evidence of insurability and overdue premiums plus interest); no cash surrender value; free-look period of 60 days. Exclusions: disability from self-inflicted injury/suicide, alcoholism or drug addiction, or war. Pre-existing disabilities are not covered. Cover terminates on grace-period expiry (if not eligible for non-forfeiture), death, receipt of the last benefit payment, no longer being SC/SPR from 1 Apr 2024, or receipt of a written cancellation notice.', trap: 'ElderShield entry age is 40 to 64; grace period is 75 days and free-look is 60 days (distinct from the general 30-day grace / 14-day free-look in Ch10).' },
      { id: 'h9-32', term: 'CareShield Life - scheme basics', fact: 'CareShield Life was introduced in 2020 and is administered by the Government on a not-for-profit basis, providing worldwide coverage with payouts for as long as one has severe disability, and protection for life. For SCs/SPRs born in 1980 or later it is universal and compulsory - automatically covered on the 30th birthday or October 2020 launch, whichever is later, even with pre-existing disabilities. SCs/SPRs born in 1979 or earlier may opt in from 6 November 2021 if they do not have severe disability, with no age limit to join; once joined they cannot leave after the 60-day free-look period.', trap: 'CareShield Life is compulsory for those born 1980 or later (covered from age 30); optional for those born 1979 or earlier. Contrast ElderShield (opt-out, entry age 40).' },
      { id: 'h9-33', term: 'CareShield Life payouts and premiums', fact: 'CareShield Life pays at least S$600 per month for as long as the insured has severe disability, with lifetime payouts and NO cap on payout duration. Payouts started at S$600/month in 2020 and increase annually until age 67 or until a successful claim, whichever is earlier; for the first five years payouts and premiums both increase 2% per year. Premiums are pre-funded and fully payable by MediSave; members pay until the year they reach age 67 or for 10 years, whichever is longer, but remain insured for life. Eligibility requires being unable to perform at least three of six ADLs; there may be a 90-day deferment period from the claim date.', trap: 'CareShield Life = at least S$600/month with NO payout duration cap (contrast ElderShield\'s 60/72-month limits). Premiums until age 67 or for 10 years, whichever is LONGER.' },
      { id: 'h9-34', term: 'CareShield Life subsidies and participation incentives', fact: 'Support includes: means-tested premium subsidies of up to 30% of base premiums for lower- to middle-income households; participation incentives of up to S$2,500 for SCs joining by 31 December 2023 (plus additional S$1,500 for Merdeka and Pioneer Generation, spread over 10 years, total S$4,000 for MG/PG); participation incentives of up to S$1,875 for SCs joining 1 Jan-31 Dec 2024 (plus additional S$1,125 for MG/PG, total S$3,000 spread over 10 years); and Additional Premium Support. CareShield Life has minimum entry age 30, no maximum entry age, no cash surrender value or death benefit; the first disability assessment fee is waived.', trap: 'Premium subsidies up to 30% of base premiums; participation incentive up to S$2,500 (by end-2023) or up to S$1,875 (in 2024) for SCs, with extra for MG/PG. Contrast MediShield Life income subsidy of up to 50%.' },
      { id: 'h9-35', term: 'Pioneer Generation Package', fact: 'The Pioneer Generation Package (introduced 2014) honours living Singaporeans who were aged 16 and above in 1965 (born on or before 31 December 1949, i.e. aged 65+ in 2014) AND obtained citizenship on or before 31 December 1986. Benefits for life: additional 50% off remaining subsidised bills at polyclinics and SOCs; CHAS special subsidies at GP/dental clinics; S$1,200 a year cash for moderate-to-severe functional disability under the Pioneer Generation Disability Assistance Scheme (paid as S$100 each month); Pioneer Generation MediShield Life Subsidies; annual MediSave top-ups S$250-S$900 for life; and CareShield Life Additional Participation Incentives of S$2,500 if joining by 31 December 2023.', trap: 'Pioneer = born on/before 31 Dec 1949 AND citizen on/before 31 Dec 1986. Disability Assistance = S$1,200/year (S$100/month) for moderate-to-severe disability.' },
      { id: 'h9-36', term: 'Merdeka Generation Package', fact: 'The Merdeka Generation Package (introduced 2019) honours living Singaporeans born 1 January 1950 to 31 December 1959 who obtained citizenship on or before 31 December 1996 (also extended to those born on or before 31 Dec 1949, citizen by 31 Dec 1996, not receiving the Pioneer Generation Package). Benefits: one-time S$100 PAssion Silver card top-up; MediSave top-up of S$200/year for five years (2019-2023); additional 25% off remaining subsidised bills at polyclinics and SOCs; CHAS special subsidies; additional Merdeka Generation MediShield Life Subsidies; and CareShield Life Additional Participation Incentives of S$2,500 if joining by 31 December 2023.', trap: 'Merdeka = born 1950-1959, citizen by 31 Dec 1996. Outpatient extra is 25% off (vs 50% for Pioneers). PAssion Silver top-up is one-time S$100.' },
      { id: 'h9-37', term: 'Majulah Package', fact: 'The Majulah Package (introduced 2023) strengthens retirement adequacy for Young Seniors born 1960 to 1973, extended to all SCs born in 1973 or earlier (including Pioneer and Merdeka Generations). Three components: (1) Earn and Save Bonus - working seniors owning no more than one property with home AV of S$25,000 or below receive up to S$1,000/year in their SA/RA (first payment March 2025); (2) Retirement Savings Bonus - seniors with retirement savings below the 2023 Basic Retirement Sum of S$99,400 get a one-time bonus of up to S$1,500 (paid December 2024); (3) MediSave Bonus - all SCs born on/before 31 Dec 1973 get a one-time bonus of up to S$1,500 in their MA (paid December 2024).', trap: 'Majulah targets Young Seniors born 1960-1973; MediSave Bonus is a one-time up to S$1,500 for all SCs born on/before 31 Dec 1973.' },
      { id: 'h9-38', term: 'IDAPE (Interim Disability Assistance Programme for the Elderly)', fact: 'IDAPE helps Singaporeans not eligible for ElderShield at its September 2002 launch (exceeded max entry age or had pre-existing disability). No premiums are payable. Qualification: unable to perform three or more of the six ADLs; a Singapore citizen born before 30 September 1932, OR born between 1 October 1932 and 30 September 1962 with pre-existing disabilities as at 30 September 2002; and per capita household monthly income of S$2,800 or less (or no income and home AV S$13,000 and below). Payout (from 1 July 2013): S$250/month up to 72 months for PCHI S$0-S$2,000; S$150/month up to 72 months for PCHI S$2,001-S$2,800. Administered by AIC.', trap: 'IDAPE payout is S$250 or S$150/month for up to 72 months, LOWER than ElderShield; assessment fees S$100 clinic / S$250 house call, reimbursed on successful application.' },
      { id: 'h9-39', term: 'ElderFund', fact: 'ElderFund is a discretionary assistance scheme launched 31 January 2020, targeted at lower-income Singapore Citizens aged 30 and older with severe disability, low MediSave balances, inadequate personal savings, who cannot benefit from CareShield Life, ElderShield or IDAPE. Eligible SCs can receive up to S$250 cash per month for as long as they remain eligible and meet the terms and conditions.', trap: 'ElderFund is a discretionary safety net (up to S$250/month) for those aged 30+ who fall outside CareShield Life, ElderShield and IDAPE.' },
      { id: 'h9-40', term: 'MediFund', fact: 'MediFund is an endowment fund set up by the Government providing a safety net for needy Singaporeans who face difficulty paying remaining healthcare bills after Government subsidies, insurance and MediSave. MediFund Silver (needy elderly) and MediFund Junior (children) are carved out for targeted assistance. Only the interest income from the capital sum is allocated to MediFund-approved institutions, each with an independent MediFund Committee. To apply one must be a Singapore citizen, a subsidised patient, have received/require treatment from a MediFund-approved institution, and have difficulty paying after Government subsidies, MediShield Life and MediSave.', trap: 'MediFund is the FINAL safety net after subsidies, insurance and MediSave; only the interest income (not the capital) is disbursed. Applicant must be a subsidised patient and a Singapore citizen.' },
    ],
  },
  {
    id: 'h10',
    num: 10,
    title: 'Common Policy Provisions',
    page: 214,
    concepts: [
      { id: 'h10-01', term: 'Sections of a policy contract', fact: 'A Health Insurance policy contract commonly has these sections: (1) Policy Schedule; (2) Insuring Clause and Definitions; (3) General Conditions; (4) Benefit Provisions; (5) Exclusions; (6) Claim Conditions; and (7) Endorsements. The sequence or header of sections may vary among insurers.', trap: 'The section order can differ by insurer, but the seven components are standard.' },
      { id: 'h10-02', term: 'Policy Schedule', fact: 'The schedule contains details of the policy owner, insured person(s), insurance coverage, coverage limits and sum insured. It is NOT a stand-alone document and must always be read together with the policy wording as one contract. It includes policy number, effective and expiry dates of cover, issue date, contract currency, names and identity numbers of owner and insured, name of plan, riders and coverage limits, premiums, coverage/benefit limits, and special provisions/endorsements.', trap: 'The schedule must be read together with the policy wording as one contract; it also lists policy-specific extra clauses or exclusions.' },
      { id: 'h10-03', term: 'Insuring Clause and key definitions', fact: 'The insuring clause (also the operative clause) states the purpose of the policy and outlines conditions under which it pays: it describes the scope of coverage, provides definitions, and sets forth the conditions under which benefits are payable. Definitions are provided for common understanding. An insured child is below 21 years old (or up to 25 if in full-time recognised higher education). A Registered Medical Practitioner/Physician is a doctor registered with the Singapore Medical Council and cannot be the insured, his spouse, child, parent, siblings or relatives.', trap: 'Insured child = below 21 (or up to 25 if studying full-time). The physician cannot be the insured or a close relative.' },
      { id: 'h10-04', term: 'Medically necessary treatment', fact: 'Medically necessary treatment is ordered by a physician and: provided for diagnosis or direct treatment of an illness/disability; cost-effective, appropriate and consistent with current professional standards of care; provided in accordance with generally accepted medical practices nationally; not for the convenience of the insured or doctor; not for prevention, health screening or promoting good health; and not experimental/investigative or for research. The fact that a physician prescribes something does not automatically make it medically necessary.', trap: 'A doctor prescribing a treatment does not by itself make it medically necessary; health screening and preventive care are excluded from the definition.' },
      { id: 'h10-05', term: 'Pre-existing condition definition', fact: 'A pre-existing condition is a condition that has existed and: for which the insured asked for or received treatment or medical advice; in respect of which he showed symptoms; of which he was aware; and which would have led a reasonable and sensible person to get medical advice or treatment before the date of policy issue or reinstatement.', trap: 'The test includes an objective element - what a reasonable and sensible person would have done - not just what the insured actually knew.' },
      { id: 'h10-06', term: 'Waiting period across product types', fact: 'For Medical Expense Insurance, the waiting period is the time from policy issue/reinstatement during which medical expenses are not covered; it applies only to illness, not accident. For Disability Income Insurance it is the period from the onset of disability during which benefits are not payable, also called the elimination or probationary period. For Long-Term Care Insurance it is the period from the first day the insured cannot perform the specified ADLs during which no benefit is payable, also known as the deferred period.', trap: 'The same term means different things: MEI (from policy start, illness only), DII (elimination/probationary period from disability onset), LTC (deferred period from first ADL failure).' },
      { id: 'h10-07', term: 'Per Policy Year Limit and Lifetime Limit', fact: 'The Per Policy Year Limit is the maximum a Medical Expense Insurance policy pays for all eligible medical expenses incurred within each policy year. The Lifetime Limit is the maximum a MEI policy pays for all eligible medical expenses incurred under the policy over its lifetime.', trap: 'Per Policy Year Limit resets each year; Lifetime Limit is cumulative over the whole policy.' },
      { id: 'h10-08', term: 'Deductible, co-insurance and pro-ration factor', fact: 'A deductible is a fixed amount of covered medical expenses the insured must first incur before the insurer pays. Co-insurance is the amount the insured must pay after the deductible; the co-insurance percentage applies to all claims except the death benefit. A pro-ration factor applies when the insured is admitted to a higher ward/hospital than entitled: the percentage is applied on actual charges (including pre- and post-hospitalisation) to reduce the benefit, reflecting the difference in Government subsidies for the ward type.', trap: 'In the worked example (plan entitlement single-bed restructured, admitted private single bed, deductible S$3,500, co-insurance 10%, pro-ration 50%): a S$10,000 bill pro-rates to S$5,000; co-insurance = 10% x (S$5,000 - S$3,500) = S$150; insurer pays S$1,350, insured pays S$8,650.' },
      { id: 'h10-09', term: 'Entire Contract, Effective Date, Premium, Free-look', fact: 'The Entire Contract Clause states the contract consists of the proposal form, declarations/questionnaires, policy contract, policy certificate, schedule of benefits, riders and endorsements, and that benefits begin on the policy start date upon receiving the first premium. The Effective Date of Cover is when the insured begins to be covered; for illness, cover starts only after the waiting period, but for accident it starts at inception. The Free-look Period lets the owner review and return the policy for a refund (less medical fees incurred), up to 14 days from receipt; the document is deemed received within seven days of despatch.', trap: 'Free-look period is up to 14 days from receipt, with the policy deemed received within 7 days of despatch (distinct from ElderShield/CareShield Life\'s 60-day free-look).' },
      { id: 'h10-10', term: 'Actively at Work and Termination of Cover', fact: 'The Actively At Work provision (found in Group Insurance and Disability Income Insurance) means in Group Insurance an employee is not eligible for coverage if absent from work due to illness/injury on the effective date; in Disability Income Insurance the cover terminates when the person is not working due to illness or termination of service. Termination of Cover: cover ceases on death, failure to pay renewal premium at end of grace period, claims reaching the limit of indemnity, or the insured reaching the specified maximum age. Termination does not affect claims arising before it, and there is no premium refund for terminating before expiry.', trap: 'Actively at Work affects Group and Disability Income covers; termination does not refund premiums and does not void a claim that arose before termination.' },
      { id: 'h10-11', term: 'Overseas treatment - emergency vs planned', fact: 'Insurers may cover emergency and/or planned overseas treatment. Emergency overseas treatment: the insurer pays the LOWER of actual hospital expenses or the reasonable expenses that would have been paid for equivalent treatment in a Singapore hospital. Planned overseas treatment (if covered): for planned inpatient/day surgery at an overseas hospital that has an approved working arrangement with a MediSave-accredited institution/referral centre in Singapore, again paying the LOWER of actual or Singapore-equivalent expenses. Benefits payable in the relevant currency at the insurer\'s exchange rate.', trap: 'Both emergency and planned overseas treatment pay the LOWER of actual overseas cost or the Singapore-equivalent reasonable expense.' },
      { id: 'h10-12', term: 'Renewal bases - cancellable, optionally, conditionally, guaranteed, non-renewable', fact: 'Cancellable: insurer can terminate any time for any reason by written notice and refund of advance premium. Optionally Renewable: insurer can refuse renewal on specified dates (policy anniversary or premium due date), and can raise premium and add coverage limitations. Conditionally Renewable: insurer can decline renewal only under specified conditions unrelated to health (e.g. age, employment); it can also raise premium. Guaranteed Renewable: insurer gives up the right to cancel or refuse renewal - non-payment of premium is the only reason for cancellation - but premiums may be increased on a class basis; guaranteed until a specified age (60/65/70/75). Non-renewable: Term Insurance (e.g. Travel Insurance, Student PA) that cannot be renewed at all.', trap: 'Guaranteed renewable: only non-payment of premium allows cancellation, and premium increases must be class-wide, not individual. Conditionally renewable non-renewal reasons cannot relate to the insured\'s health.' },
      { id: 'h10-13', term: 'Misstatement of age/gender, Grace Period, Reinstatement, Incontestability', fact: 'Misstatement of Age or Gender: the insurer adjusts premium to the correct age/gender, refunding excess or collecting shortfall; if at the correct age the insured would not have been eligible, no benefit is payable. Grace Period: a stated period to pay renewal premium after the due date, 30 days for most policies, with coverage remaining in force. Reinstatement: after lapse for non-payment, the owner must complete a health declaration and pay overdue premium with interest; the insurer may decline; cover is only effective after reinstatement. Incontestability (for Health riders on Life policies): makes the policy indisputable after a minimum period (usually one year), except for fraud.', trap: 'General grace period is 30 days for most policies (contrast ElderShield\'s 75 days). Incontestability applies after usually one year, except for fraud.' },
      { id: 'h10-14', term: 'Change of Occupation and Co-ordination of Benefits', fact: 'Change of Occupation (in many Disability Income policies): the insurer may adjust premium or benefit amount when the insured changes occupation - reducing the maximum benefit if he moves to a more hazardous occupation, or reducing the premium if he moves to a less hazardous one. Co-ordination of Benefits (also Over-insurance or Contribution provision) prevents profiting from a claim: benefits are reduced if the insured is eligible for reimbursement from other sources. It applies whether or not the insurer was notified of other coverage, and the insurer may demand return of benefits already paid if it later learns of other sources.', trap: 'More hazardous occupation reduces the benefit amount; less hazardous reduces the premium. Co-ordination of Benefits applies even if other coverage was not disclosed at application.' },
      { id: 'h10-15', term: 'Cancellation, Change of Plan, Currency, Last Payer Status', fact: 'Cancellation: the owner may cancel by advance written notice or by letting the policy lapse; unused premium may not be refunded, and the insurer is not liable for charges incurred after cancellation takes effect. Change of Plan: MEI allows upgrade/downgrade; upgrading needs satisfactory evidence of insurability at the owner\'s expense, requested at least 30 days before the renewal/premium due date; conditions covered before a plan change remain covered at pre-change limits. Currency: claims are generally paid in Singapore currency, foreign charges converted at the insurer\'s exchange rate. Last Payer Status (in MediShield Life and Private IPs): the insured must first claim from other medical insurance/employee benefits before claiming under MediShield Life or a Private IP.', trap: 'Last Payer Status means MediShield Life/IP pays LAST - the insured must exhaust other medical insurance/employer benefits first.' },
      { id: 'h10-16', term: 'Nomination of Beneficiaries (NOB)', fact: 'NOB under Part 3C of the Insurance Act 1966 (from 1 September 2009) lets policyowners of Life or A&H policies with death benefits distribute policy benefits to nominees. CI policies with built-in death benefits fall under the NOB framework; a policyowner aged 18 or above can make a nomination. Trust/Irrevocable Nomination (Section 132): the insured loses all ownership rights and needs written consent of all nominees to revoke. Revocable Nomination (Section 133): the insured retains ownership and can change/add/remove nominees without their consent.', trap: 'Section 132 = Trust/Irrevocable (loses ownership, needs nominees\' consent to revoke); Section 133 = Revocable (retains ownership, free to change). NOB applies to policies with death benefits.' },
      { id: 'h10-17', term: 'Policy Owners\' Protection Scheme (PPF)', fact: 'MAS supervises licensed insurers for stability and sound risk management but does not guarantee individual institutions, so the Policy Owners\' Protection (PPF) Scheme protects policy owners if a member life or general insurer fails. Its scope includes individual and group short-term or long-term A&H policies (e.g. Hospital Income, Medical Expense, Personal Accident, Disability Income, Long-Term Care). The PPF Scheme is administered by the Singapore Deposit Insurance Corporation (SDIC); coverage is automatic with no action needed from policy owners.', trap: 'PPF is administered by SDIC and coverage is automatic. MAS supervises but does not guarantee individual insurers.' },
      { id: 'h10-18', term: 'Benefit Provisions and Exclusions', fact: 'The Benefit Provisions section details what the policy covers, what will be paid, the conditions establishing the insurer\'s liability, and applicable limitations; it must be clear yet broad enough to cover any conceivable claim. For a Medical Expense Insurance policy, benefits include daily room/board and medical related services, Intensive Care Unit charges, and Surgical Benefits (surgeon\'s, anaesthetist\'s, and operating theatre/facility fees). Exclusions cover charges above reasonable charges, illness within the waiting period, pre-existing conditions, and categories such as routine/cosmetic procedures, refraction/eyeglasses, dental, pregnancy, infertility/sterilisation, mental/nervous disability, STD/AIDS/HIV, self-inflicted injury or substance abuse, criminal/riot acts, war and nuclear risks, morbid obesity, and non-medically-necessary confinement.', trap: 'No benefit is paid for charges exceeding reasonable charges, illness within the waiting period, or pre-existing conditions, in addition to the listed exclusion categories.' },
      { id: 'h10-19', term: 'Claim Conditions', fact: 'Claim conditions include: Notification of Claim (timely notice of loss to the insurer); Submission of Claim (the owner must, at his own expense, submit certificates, forms, original bills, receipts and evidence required; may be submitted electronically by a hospital/clinic via MediClaim); Right to Examine (the insurer may have the insured examined by its appointed doctor before paying, and may require a post-mortem where legally allowed); and Mediation/Arbitration and Legal Action provisions.', trap: 'The policy owner bears the expense of submitting claim documents; electronic submission is via the MediClaim system.' },
      { id: 'h10-20', term: 'Dispute resolution and legal action', fact: 'Any dispute should first go to the Financial Industry Disputes Resolution Centre Ltd (FIDReC), referred within six months from the date of failure to reach agreement with the insurer. If it cannot be referred to or dealt with by FIDReC, the dispute goes to arbitration under the Arbitration Rules of the Singapore International Arbitration Centre; the insurer is not legally responsible until the owner has received an award under arbitration. If mediation and arbitration fail, legal action may follow, but no action may be brought until 60 days after satisfactory proof of claim is furnished. Policies are governed by the laws of the Republic of Singapore.', trap: 'FIDReC first (within 6 months), then arbitration (SIAC), then legal action; no legal action until 60 days after satisfactory proof of claim.' },
      { id: 'h10-21', term: 'Endorsements', fact: 'An endorsement is a separate document that modifies the policy to which it is attached. Endorsements can amend or add terms so the policy conforms to legislative requirements, or serve as supplementary agreements providing optional benefits not in the basic policy (requiring an additional premium), e.g. maternity benefits added to an H&S policy. Endorsements on exclusions restrict coverage by excluding a specific pre-existing condition or certain activities; an insurer may require this as a pre-condition (a counter-offer) - if the insured signs and accepts, a binding contract is formed.', trap: 'Endorsements can either ADD benefits (extra premium) or RESTRICT coverage (exclusions); an exclusion endorsement can be a counter-offer that becomes binding once signed.' },
    ],
  },
  {
    id: 'h11',
    num: 11,
    title: 'Health Insurance Pricing',
    page: 237,
    concepts: [
      { id: 'h11-01', term: 'Morbidity rate (primary pricing factor)', fact: 'Morbidity is the rate at which disease or illness occurs within a group of people over a period of time. It is the PRIMARY consideration in health insurance pricing. On average, the morbidity rate of women is higher than men, which is why women pay higher premium rates than men for most Health Insurance policies.', trap: 'Health insurance is priced on morbidity (incidence of illness), not mortality (incidence of death). Mortality is the Life Insurance measure.' },
      { id: 'h11-02', term: 'Investment income', fact: 'Investment income is the money earned when an insurer invests the premiums it receives. Not all premiums received each year are needed to pay that year\'s claims, so the surplus is invested to earn more. Investment income is an additional source of funds and helps to REDUCE the premiums insurers have to charge.', trap: 'Investment income lowers premiums; it does not raise them. Operating expenses raise premiums.' },
      { id: 'h11-03', term: 'Operating expenses', fact: 'Operating expenses INCREASE the price of insurance. Insurers collect premiums not only to cover the cost of insurance (claims) but also to cover the cost of running the company: staff salaries, commissions for sellers, taxes, office rent, advertising, computer systems and supplies.' },
      { id: 'h11-04', term: 'Medical inflation', fact: 'Medical inflation is the consistent upward trend in medical claim costs experienced by both individual and group plans. Rising claims are associated with increases in medical care charges, medical advancement and higher utilisation of services, especially with a growing ageing population. Insurers factor in medical inflation so premiums remain adequate to cover rising costs.' },
      { id: 'h11-05', term: 'Impact of epidemic/pandemic on general population', fact: 'Following the profound impact of Covid-19 (new vaccination developments, mandatory government rules), insurers now take into consideration the change in health of the general demographics and its potential impact on health insurance claims when pricing health insurance.' },
      { id: 'h11-06', term: 'Scope of benefits covered', fact: 'Premiums are higher for plans with richer and higher benefit limits, smaller deductible and smaller co-insurance. Adding each benefit increases the final premium. For H&S policies such as Integrated Shield Plans, coverage for private hospital treatment is more expensive than coverage for public hospital treatment.', trap: 'Smaller deductible and smaller co-insurance mean HIGHER premiums (insurer bears more). A larger deductible/co-insurance lowers the premium.' },
      { id: 'h11-07', term: 'Insurer\'s profit', fact: 'Insurers enter the market primarily to profit. When pricing a product they add a profit margin (loading) into the premium. The loading depends on the insurer\'s profit target and strategy and the nature of the business; an insurer chasing market share may settle for a thinner profit margin.' },
      { id: 'h11-08', term: 'Modes of premium payment', fact: 'Mode of payment is the frequency premiums are payable: annually (once a year), bi-annually (twice a year), quarterly (once every three months) or monthly (once a month). Premium increases slightly as payment frequency increases, to recoup additional billing/handling costs and the lost investment income from not investing the full annual premium at once. A monthly premium is slightly higher than a sixth of a semi-annual premium; a semi-annual premium is slightly higher than half of an annual premium.', trap: 'More frequent payment means a slightly HIGHER total premium, not a discount.' },
      { id: 'h11-09', term: 'Extent of underwriting', fact: 'Gathering medical information at application can be lengthy and tedious. Some insurers choose to do minimal risk assessment by reducing the number of health declarations on the proposal form; to do so, they charge a HIGHER premium.', trap: 'Less underwriting means a HIGHER premium (insurer takes on more unknown risk), not a lower one.' },
      { id: 'h11-10', term: 'Rating parameter - Age', fact: 'Age is a key premium-rating parameter for both individual and group plans. Different age groups differ in claim frequency and claim severity; e.g. a 50-year-old is more likely to need a longer recovery period than a 30-year-old.' },
      { id: 'h11-11', term: 'Rating parameter - Gender', fact: 'Statistics show women in general make more medical claims than men, so a female pays a higher premium for Health Insurance such as Long-Term Care and Critical Illness than a male of the same age. For simplicity not all health insurance premiums are gender-differentiated: MediShield Life and Integrated Shield Plan premiums depend on age but NOT gender.', trap: 'MediShield Life and IP premiums are age-based only, not gender-differentiated, even though most other health premiums differ by gender.' },
      { id: 'h11-12', term: 'Rating parameters - Health status and Lifestyle', fact: 'Health status is a major consideration: an individual with a pre-existing condition can expect special underwriting terms or even a decline. Lifestyle also affects the premium; participation in a hazardous sport (recreational flying, mountaineering, scuba-diving) requires extra premiums or activity exclusions. The MOST important lifestyle factor for determining premium rate is smoking, and a non-smoker pays a lower premium than a smoker.', trap: 'The single most important lifestyle factor for pricing is smoking.' },
      { id: 'h11-13', term: 'Rating parameter - Occupation', fact: 'Occupation strongly influences risk. Insurers group occupations into risk classes according to the risk of accident or illness and set premiums on that occupational hazard; e.g. a high-rise construction worker is more likely to suffer injury than an office administrator. Not every occupation is on the risk-class list but most jobs can be broadly classified. The higher the occupational risk of injury or illness, the higher the premium.' },
      { id: 'h11-14', term: 'Rating parameter - Persistency', fact: 'Persistency measures how long customers renew their policies and is used to price both Individual and Group Health Insurance. Persistency usually improves as policies age and varies by age group; younger insureds (e.g. ages 20-29) may have poorer persistency than older insureds (e.g. ages 50-59), who see the policy as more valuable because they may struggle to satisfy underwriting for a new policy. If persistency is expected to be high, the insurer will REDUCE the premium charged.', trap: 'High expected persistency lowers premiums. Younger insureds tend to have poorer (lower) persistency than older ones.' },
      { id: 'h11-15', term: 'Portfolio claims experience and IBNR', fact: 'Claims experience of the portfolio strongly influences premiums; collected premiums must, above all other expenses, be sufficient to pay expected claims. Total claims of a portfolio comprise (i) paid claims, (ii) pending claims and (iii) Incurred But Not Reported (IBNR) claims. IBNR are potential claims that have occurred but not yet been reported to the insurer (e.g. due to delayed reporting); insurers must estimate IBNR and set up a reserve. For group plans, claims experience becomes more important as group size grows and more years of data are available.', trap: 'IBNR = Incurred But Not Reported: the loss has already occurred but has not yet been reported to the insurer.' },
      { id: 'h11-16', term: 'Claims-based pricing', fact: 'Some insurers use claims-based pricing to adjust an individual\'s premium based on his claims on the policy. For example, a renewal discount may be given if no claims are made; and if a claim is made, the insured is not penalised where he kept claim costs low by electing treatment at a public hospital.' },
      { id: 'h11-17', term: 'Group participation level and anti-selection', fact: 'For voluntary group plans the extent of employee participation is an important rating parameter. Low participation gives a greater chance that a higher-than-normal proportion of individuals with health issues will seek coverage - this is called anti-selection. High participation gives a good mix of healthy lives to compensate for anti-selection risk, so many insurers vary premium rates based on the participation level.', trap: 'Low participation raises anti-selection risk (unhealthy self-select in); high participation dilutes it with healthy lives.' },
    ],
  },
  {
    id: 'h12',
    num: 12,
    title: 'Health Insurance Underwriting',
    page: 244,
    concepts: [
      { id: 'h12-01', term: 'What is underwriting', fact: 'Underwriting is the process whereby an insurer assesses the risk and determines whether to accept an application and, if so, on what terms. It ensures premiums charged correspond closely with the risk each proposer represents. Life Insurance underwriting is concerned with mortality (incidence of death); Health Insurance underwriting is concerned with morbidity (rate of disease/illness in a group over time).', trap: 'Health underwriting = morbidity; Life underwriting = mortality.' },
      { id: 'h12-02', term: 'Medical factors - history and current physical condition', fact: 'Factors affecting risk are medical and non-medical. Medical factors cover past medical history and current physical conditions. Insurers review past medical history for possibility of recurrence, effect on general health, possible later complications and normal progression of any impairment. Acute disorders (e.g. simple bone fractures, appendectomy) may be disregarded if recovery was prompt and complete with no residual impairment. Current physical condition is assessed via proposal-form statements and medical exams, plus tests like urinalysis, blood studies, fasting glucose, cognitive assessments and ECGs depending on age and coverage amount.' },
      { id: 'h12-03', term: 'Financial factor (non-medical)', fact: 'Financial information (income, assets, debts) lets the underwriter gauge whether the life insured is over-insured or can keep paying premiums throughout the term. It is especially important for Disability Income Insurance: the benefit amount applied for must be reasonable and not higher than 75% of the life insured\'s current income. Both earned and unearned income plus net worth are considered, since a high net worth reduces the insured\'s incentive to return to work.', trap: 'The DII benefit ceiling is 75% of current income - a commonly tested figure.' },
      { id: 'h12-04', term: 'Occupational, age and residency factors', fact: 'Occupation influences risk through accident hazards or health hazards (e.g. asbestos handling can cause asbestosis over time). Age: medical problems increase with age, so underwriting guidelines require more medical exams/tests and APS for older proposers and more thorough investigation. Residency: past, current and future residency matter; underwriters watch for applicants travelling to war zones, health-risk areas or politically unstable regions.' },
      { id: 'h12-05', term: 'Avocation, lifestyle risks and habits (proximate cause)', fact: 'Additional considerations are avocation/lifestyle risks (drug abuse, multiple sexual partners, navigational recreational activity, hazardous occupations, and hazardous sports such as motor racing, mountaineering, parachuting and scuba diving). Insurers may require a supplementary lifestyle questionnaire. Habits - smoking, alcohol and drug use - represent serious risks that can cause health problems or accidents; this is also known as the Proximate Cause.' },
      { id: 'h12-06', term: 'Factors more important for each Health Insurance type', fact: 'Medical Expense Insurance: medical history and current physical condition are basic indicators; pre-existing conditions are usually excluded (e.g. all heart conditions excluded for a hypertensive proposer). Disability Income Insurance: size and stability of earnings and overall financial situation, using occupational risk classifications for loadings. Long-Term Care Insurance: two key factors are detecting early cognitive impairment and assessing morbidity risk (ability to perform ADLs); any musculoskeletal condition is a potential LTC risk. Critical Illness Insurance: besides medical history and current condition, smoking habit and family history matter (some cancers and diabetes cluster in families). Managed Healthcare: similar to Medical Expense; for groups, age/gender are strong factors (older groups higher morbidity; many females of child-bearing age raise costs).', trap: 'LTC key factors = early cognitive impairment + morbidity risk. CI adds smoking habit + family history.' },
      { id: 'h12-07', term: 'Full Medical Underwriting', fact: 'The life insured completes a lengthy health declaration; the insurer reviews it and may request an APS or medical exam. Pre-existing conditions likely to need future treatment are usually excluded along with related conditions, and the insurer provides a written offer stating the excluded conditions (which the insured may later ask to review). Advantage: although it takes more time, it gives the insured certainty as to what is covered right at the start rather than at claim time.', trap: 'Full Medical Underwriting should ALWAYS be the starting point; advisers must not default to moratorium for their own convenience.' },
      { id: 'h12-08', term: 'Moratorium Underwriting (Point-of-Claim)', fact: 'Also called Point-of-Claim Underwriting and used for Medical Expense Insurance. No health declaration or medical exam at application; instead the insurer sets a waiting period (usually two to five years). Any pre-existing condition for which the insured received treatment/medication, was advised on, or had symptoms of (whether or not diagnosed) immediately before the commencement date is excluded. If the insured has no symptom, treatment, medication or advice for those conditions during the waiting period, they become covered once the period ends. Long-term conditions (stroke, kidney failure, heart bypass, dementia) needing continuous treatment will NEVER be covered even after the moratorium, as they cannot meet the conditions; and if declared under full underwriting they are permanently excluded. Advantage: the policy issues quickly.', trap: 'Moratorium underwriting still EXCLUDES pre-existing conditions at outset; cover for them only starts if the moratorium (2-5 years) is satisfied symptom/treatment-free. Long-term conditions are never covered.' },
      { id: 'h12-09', term: 'Simplified Issuance Offer (SIO)', fact: 'In SIO the life insured is asked only a few questions whose answers determine approval; there is no medical examination. SIO is more common where insurers market via direct or online channels. It gives coverage quickly compared with days/weeks under Full Medical Underwriting, but premium is higher due to the greater risk the insurer takes.', trap: 'SIO asks a few questions; GIO asks NO medical questions at all - do not confuse the two.' },
      { id: 'h12-10', term: 'Guaranteed Issuance Offer (GIO)', fact: 'GIO requires no medical questions and no medical examination. The insurer guarantees to issue the policy so long as the applicant is eligible, usually an age requirement (e.g. only offered below age 60). To minimise anti-selection, GIO policies have smaller coverage with pre-existing conditions permanently excluded. GIO is used for Hospital Income Plans or Single Critical Illness Plans sold via direct/online channels; premium is higher for the convenience of guaranteed cover.', trap: 'GIO = no questions, guaranteed issue, but smaller cover and pre-existing conditions permanently excluded.' },
      { id: 'h12-11', term: 'Group underwriting - reason for existence and stability', fact: 'A group is underwritten as a whole before individual member risks. Reason for existence: the group must have been formed for a purpose (e.g. running a business) other than only buying insurance, to reduce anti-selection; members must be actively at work full-time with predictable incomes. Group stability: unusually high turnover raises admin costs, while an overly static group ages without younger entrants and becomes riskier at each renewal. The ideal group has a steady flow of new members replacing leavers, without massive influx or outflow.' },
      { id: 'h12-12', term: 'Group underwriting - size, nature of business, employee classes, participation', fact: 'Group size: bigger groups spread and diversify risk and allow efficient, lower-cost administration. Nature of business: some industries (oil rigging, timber logging) are high-risk. Employee classes based on job title, salary or length of service create over-representation effects: too many highly-paid can raise average claims, too many low-income can raise turnover. Level of participation: for contributory (voluntary) plans insurers normally require a minimum participation of eligible members, typically between 70% and 90%, to guard against anti-selection and reduce admin costs.', trap: 'Minimum participation requirement for contributory group plans is typically 70% to 90% of eligible members.' },
      { id: 'h12-13', term: 'Group underwriting - age/gender, persistency, claims, inflation, utilisation, free cover limit', fact: 'Age increases group mortality; gender ratio matters because females have lower mortality but higher morbidity. Underwriting requirements depend on group size and product type (e.g. a 20-member Group Medical Expense plan may skip individual Health Declarations, but a Disability Income plan requires each member to complete one, with medicals for sums exceeding the free cover limit). Expected persistency: insurers spread acquisition costs over three to five years and avoid short-lived groups. Past claims experience predicts future claims. Medical inflation and medical utilisation rate and trend (rising average age, new drugs) also affect risk. The free cover limit is the maximum coverage granted to each member without a health declaration; excess above it is underwritten.', trap: 'Free cover limit = maximum cover per member with NO health declaration; anything above it must be underwritten.' },
      { id: 'h12-14', term: 'Sources of underwriting information', fact: 'The five sources are: (a) Proposal Form - the primary source; (b) Agent\'s Statement; (c) Medical Examinations/Tests; (d) Attending Physician\'s Statement (APS); and (e) Supplementary Questionnaires. More information is required for older insureds and for policies with higher benefits and longer coverage. The proposal form must, under the Insurance Act 1966, carry a warning citing Section 23(5) requiring full and faithful disclosure of all material facts, otherwise nothing may be payable under the policy.', trap: 'The proposal form is the PRIMARY source of underwriting information. The APS is completed by the attending physician when deeper medical insight is needed.' },
      { id: 'h12-15', term: 'Medical exam tests and APS', fact: 'Insurers may require medical exams for Disability Income, Critical Illness and Long-Term Care Insurance. Common tests include ECG, chest X-ray, micro-urinalysis, blood profile analysis, HIV antibody test and (for LTC) cognitive assessment. The cost of the exam at application is borne by the insurer unless the policy is subsequently not taken up. An APS is a standard pre-printed form completed by the attending physician from the proposer\'s medical records, required when the underwriter needs insight not available from the medical exam.', trap: 'Exam cost is borne by the insurer UNLESS the policy is not taken up (then the applicant bears it).' },
      { id: 'h12-16', term: 'Representative as field underwriter', fact: 'Because the insurance representative has personal contact with the client, he is in the best position to select the client and is considered the FIELD UNDERWRITER. He should establish the client\'s motivation and needs, go through proposal-form questions ensuring truthful and faithful disclosure, extract full details for any \'Yes\' answers, and ensure the form is completed and signed in his presence to speed processing. Knowing underwriting guidelines (when exams/questionnaires are needed) also expedites the process.', trap: 'The insurance representative acts as the \'field underwriter\'.' },
      { id: 'h12-17', term: 'Final underwriting decision - standard vs sub-standard', fact: 'Standard risk: policy issued at the rate-book premium once premium is fully paid; usually 80% to 90% of proposals are accepted at standard rates. Sub-standard risk: people with medical or non-medical impairments; the insurer modifies the cover applied for. Most insurers have declination rates below 10%.', trap: 'About 80-90% accepted at standard rates; declination rate is below 10%.' },
      { id: 'h12-18', term: 'Modifications of cover, postponement and decline', fact: 'Modifications include: Specific Exclusions (an endorsement stating a particular risk, e.g. \'hernia\' or \'disease of the stomach or intestines\', will not be paid - common in Medical Expense Insurance); Extra Premiums (common for Disability Income and Critical Illness, rarely used in Medical Expense); and Modification of Benefits (reduced monthly benefit, longer deferred period, shorter benefit period; e.g. an insurer may cap the benefit period at five years for any risk needing over 50% extra premium). Postponement: the underwriter offers no terms now but will reconsider later (e.g. six months after a surgery). Decline: the most drastic action, used only for serious medical, occupational or financial reasons.', trap: 'Specific exclusions are common in Medical Expense Insurance; extra premiums are common in DII/CI but rare in Medical Expense.' },
      { id: 'h12-19', term: 'Commencement of risk', fact: 'For a sub-standard risk, the insurer communicates the terms of acceptance to the proposer before issuing the policy; if the proposer agrees to the terms in the letter of acceptance and pays the premium, cover is effected and the policy issued. For a standard risk, the policy is issued upon premium payment.' },
    ],
  },
  {
    id: 'h13',
    num: 13,
    title: 'Notice No: MAS 120 - Disclosure And Advisory Process Requirements for Accident and Health Insurance Products',
    page: 270,
    concepts: [
      { id: 'h13-01', term: 'Objective, issue and scope of MAS 120', fact: 'MAS first issued Notice No: MAS 120 - Disclosure And Advisory Process Requirements For Accident And Health (A&H) Insurance Products on 30 January 2004 (effective 1 April 2004); the last amendment was 1 June 2022. It is issued under Sections 67, 72 and 154(4) of the Insurance Act 1966 and comprises BOTH mandatory requirements and best-practice standards on disclosure of information and provision of advice for A&H policies and life policies that provide A&H benefits.', trap: 'MAS 120 has two parts: Part I mandatory requirements AND Part II non-mandatory best-practice standards. Issued 30 Jan 2004, last amended 1 June 2022.' },
      { id: 'h13-02', term: 'Where MAS 120 does not apply', fact: 'The Notice generally applies to all direct insurers and licensed/exempt financial advisers (and their representatives/brokers/agents) who provide advice on or arrange A&H policies and life policies providing A&H benefits. It does NOT apply where: (a) such policies are in respect of reinsurance of liabilities under insurance policies; and (b) such policies provide that A&H benefits are paid out only if the insured becomes totally and permanently disabled as defined under the policy.', trap: 'Two exclusions from scope: reinsurance, and policies paying A&H benefits only on total-and-permanent disability.' },
      { id: 'h13-03', term: 'Structure - Part I Divisions', fact: 'Part I (Mandatory) has: Division 1 general requirements for A&H policies; Division 1A disclosure requirements for A&H policies; Division 2 disclosure requirements for life policies containing A&H benefits; Division 3 additional disclosure requirements for direct insurers; Division 4 requirements on provision of advice relating to A&H policies; Division 5 requirements on provision of advice relating to life policies containing A&H benefits; Division 6 offences. Part II is non-mandatory best-practice standards.' },
      { id: 'h13-04', term: 'Division 1 - the \'Shield\' naming rule', fact: 'No direct insurer shall use the word \'Shield\' in the name, description or title of any A&H policy it issues UNLESS that policy is a Medisave-approved policy. (A Medisave-approved policy means an integrated shield plan, non-integrated shield plan or supplementary disability insurance policy.)', trap: '\'Shield\' may only be used for Medisave-approved policies.' },
      { id: 'h13-05', term: 'Key definitions', fact: '\'Health policy\' means an A&H policy that is not a personal accident policy. \'Personal accident policy\' pays A&H benefits only on injury/disability from accident, death by accident, or a combination. \'Switching\' includes terminating a policy and replacing it with another. \'Upgrading\' means varying terms or terminating an existing policy to buy a new policy with the SAME insurer for better benefits. A \'selected client\' meets any TWO of: 62 years or older; not proficient in spoken or written English; below GCE \'O\'/\'N\' level or equivalent.', trap: 'Switching = replace with another (possibly different) insurer\'s policy; upgrading = better benefits with the SAME insurer. A \'selected client\' must meet any TWO of the three criteria.' },
      { id: 'h13-06', term: 'Division 1A - intermediary and representative disclosure', fact: 'An A&H insurance intermediary must disclose to the policy owner IN WRITING its business name, business address and telephone number. An A&H insurance representative must disclose in writing his name and the intermediary/intermediaries for which he acts. Any change to this information must be communicated in writing at the next dealing right after the change.' },
      { id: 'h13-07', term: 'Division 1A - remuneration and conflict of interest', fact: 'The intermediary must disclose in writing all remuneration - including any commission, fee and other benefit - that it has received or will receive for advising on or arranging any A&H policy. It must also disclose in writing any actual or potential conflict of interest arising from any connection or association with any insurer, including facts that may compromise its objectivity.' },
      { id: 'h13-08', term: 'Division 1A - disclosure when providing advice (para 17)', fact: 'When dealing with an individual policy owner, the intermediary must disclose and explain: (a) nature and objective of the policy (whether health or personal accident, and whether it reimburses costs, provides income during disability, pays lump sums, or a combination); (b) details of the insurer including its business address; (c) contractual rights and obligations, including that the owner is responsible for accuracy/completeness of information and that mis-statement or non-disclosure may affect validity, plus premium amount, frequency, period and whether the rate is guaranteed or non-guaranteed; (d) benefits (when policy moneys are/are not paid, amount, timing, guaranteed or not, any lien); (e) risks (whether the insurer may alter terms or decline to renew/unilaterally terminate); (f) free-look period provision and how to exercise it; (g) claim/termination procedures, charges and restrictions; and (h) all warnings, exclusions and disclaimers.', trap: 'Para 17\'s eight items (a)-(h) are the core \'disclosure when providing advice\' checklist. Contractual-rights disclosure must state the premium is guaranteed or non-guaranteed.' },
      { id: 'h13-09', term: 'Group policy and personal accident disclosure', fact: 'For a personal accident policy, the intermediary must ensure the policy owner is aware policy moneys are paid as a result of accident ONLY. For a group policy, the intermediary must disclose the para-17 information plus the duration of coverage and whether the premium qualifies for special tax treatment. Where any insured person in a group is liable to pay any premium, the intermediary must disclose to every person in the group as if dealing with them individually.' },
      { id: 'h13-10', term: 'Marketing, telemarketing and direct marketing', fact: 'A representative may only use marketing materials approved (for an integrated shield plan, by the issuing insurer; for other A&H policies, by the intermediary he acts for). For telephone marketing of NON-Medisave-approved A&H policies designed to solicit and close a sale where no advice is provided, the intermediary must warn the recipient he may wish to seek advice first, and that if he does not he should consider whether the policy is suitable, and must keep a record of all calls for audit. Direct-response advertising designed to solicit and close a sale must carry a prominent warning covering the same points plus the ability to terminate under the free-look provision (with the insurer able to recover underwriting expenses).', trap: 'An intermediary generally must NOT close the sale of a Medisave-approved policy over the phone (para 24A), subject to the temporary exemption that ran 13 Apr 2020 to 30 Sep 2022.' },
      { id: 'h13-11', term: 'Division 3 - additional disclosure by direct insurers', fact: 'Direct insurers must prepare benefit illustrations/product summaries to industry standards and disclose prescribed information in each document for integrated and non-integrated shield plans. Product summaries, conditional offer letters and termination letters for individual medical expense policies (and A&H policies that are not Medisave-approved) must use font size Times New Roman 10-point or larger with standardised disclosure statements. Where terms may be varied, amended or added, the insurer must disclose existing and new terms, explain how they are accepted, and furnish this in writing to the policy owner at least 30 DAYS before the change takes effect.', trap: 'Two specifics often tested: required font is Times New Roman 10-point or larger, and variation of terms must be notified in writing at least 30 days beforehand.' },
      { id: 'h13-12', term: 'Division 4 - reasonable basis for advice', fact: 'No intermediary shall provide advice on a health policy to a person who may reasonably be expected to rely on it without a reasonable basis. There is no reasonable basis unless: (a) for the purpose of ascertaining the advice is appropriate, having regard to the person\'s objectives, financial situation and particular needs, the intermediary gave reasonable consideration to and investigated the subject matter; and (b) the advice is based on that consideration and investigation. Division 4 does NOT apply where no recommendation is made or only factual information is provided, nor to advice on any ElderShield policy.', trap: 'Division 4 does not apply to purely factual/no-recommendation situations or to ElderShield advice.' },
      { id: 'h13-13', term: 'Division 4 - Know-Your-Client (individual)', fact: 'To advise an individual taking into account objectives, financial situation and particular needs, the intermediary must collect and DOCUMENT: (a) the owner\'s objectives - the event(s) protected against, the nature of benefit (lump sum vs periodical, and whether tied to actual cost), and the class of hospital ward sought; (b) employment status; (c) financial situation (assets, liabilities, cash flow, income); (d) source and amount of regular income; (e) financial commitments; (f) any existing health policy including CPF-scheme policy moneys; (g) any medical conditions the insured may have; and (h) for dependants to be insured, the information in (a)-(e) for them.', trap: 'KYC information must be both collected AND documented. Note items (a)-(e) are also required for dependants who are to be insured.' },
      { id: 'h13-14', term: 'Division 4 - Know-Your-Client (group) and basis-of-advice warning', fact: 'For a group policy the intermediary must collect and document: the objectives (financial impact protected against, mode of payment, class of ward), the size and composition of the group (breakdown by gender, age, income, occupation), the claims history of the group, and any medical conditions of members. The intermediary must highlight in writing that the information provided is the basis on which advice is made, and that inaccurate or incomplete information may affect the suitability of the advice.' },
      { id: 'h13-15', term: 'Division 4 - Needs analysis', fact: 'The intermediary must analyse the information provided and identify the type of policy suitable for the insured. If unable to identify a suitable policy, it must inform the policy owner. It must explain to the owner the basis for its advice, and that basis must be documented. Where the owner declines to provide requested information, or declines the advice and chooses another (unadvised) policy, the intermediary may proceed but must document the owner\'s decision and inform him it is his responsibility to ensure suitability. Where the owner chooses to receive no advice at all, that decision must be properly documented.' },
      { id: 'h13-16', term: 'Division 4 - Documentation and record keeping', fact: 'The intermediary must furnish the policy owner, BEFORE he signs the application (or consents to withdrawal/surrender of a health policy), a document containing: (a) a summary of the information gathered under the KYC paragraphs; and (b) any advice provided and its basis; plus, where applicable, a statement that the owner does not want to provide the requested information, does not accept the advice and has chosen another policy, or does not want to receive any advice.', trap: 'The documentation must be given BEFORE the owner signs the application form - not afterwards.' },
      { id: 'h13-17', term: 'Division 4 - Switching of A&H policies', fact: 'An intermediary must not advise an individual to switch from an original A&H policy to a replacement policy in a manner detrimental to the insured. In assessing whether a switch is detrimental, MAS has regard to: (a) whether the owner suffers any penalty for terminating the original; (b) whether the owner incurs transaction cost without gaining real benefit; (c) whether the replacement gives a lower benefit at higher or same cost, or the same benefit at higher cost; and (d) whether the replacement is less suitable. The intermediary must disclose in writing any fee/charge the owner bears and the changes in level of benefits so the owner can make an informed decision.', trap: 'The four detriment factors (a)-(d) are frequently tested. Switching must follow all Division 4 advice requirements plus written disclosure of fees and benefit changes.' },
      { id: 'h13-18', term: 'Division 6 - offences', fact: 'Any person who fails to comply with any requirement under any paragraph in Part I of MAS 120 is guilty of an offence punishable under Section 142(3) of the Insurance Act 1966.', trap: 'Only breaches of Part I (mandatory) are offences; Part II is non-mandatory best practice and carries no offence.' },
      { id: 'h13-19', term: 'Part II - best practice and monitoring of switching', fact: 'Part II best-practice standards: information disclosed should be in plain language, with jargon explained, objective, unbiased, unambiguous, prominently warning of key terms, kept up to date, and go beyond mere compliance to help owners make informed decisions. For monitoring switching of long-term A&H policies, the intermediary should ensure the policy owner declares IN WRITING whether he was advised by the representative to switch (including where the new policy has different benefits or the terminated policy came from another intermediary). If advised to switch, the owner should further declare whether his attention was drawn to the costs/disadvantages and whether he still wishes to proceed. The representative\'s SUPERVISOR should review each switching recommendation and indicate in writing whether he agrees, considering the para-44 detriment factors.', trap: 'The switching declaration and supervisor review sit in Part II (best practice), and the supervisor applies the same para-44 detriment factors used for mandatory switching assessment.' },
    ],
  },
  {
    id: 'h14',
    num: 14,
    title: 'Financial Needs Analysis',
    page: 303,
    concepts: [
      { id: 'h14-01', term: 'Needs selling vs product selling', fact: 'Needs selling is more desirable than product selling because it is (a) service-oriented, (b) not pressure selling, and (c) relationship-based. In needs selling you discover the client\'s needs and advise on the most suitable product and how much to buy, spending more time on his situation than on your product; in product selling you assume the client needs your product and go straight into it, creating buying pressure and a relationship dependent only on how much he likes the product.' },
      { id: 'h14-02', term: 'The FNA process and fact-finding', fact: 'The needs-analysis process is: fact-finding, identifying and quantifying needs, product recommendations, presenting recommendations, and review. Fact-finding is the process of obtaining answers to a series of questions about a prospective client\'s personal circumstances, finances and future ambitions, giving a proper basis to recommend suitable A&H or other products. Knowing the client via a Fact-Find Document is a requirement under Notice No: MAS 120.', trap: 'Fact-finding (Know-Your-Client) is not optional - it is a MAS 120 requirement.' },
      { id: 'h14-03', term: 'Fact-Find Document - Application Type', fact: 'The client ticks one of three application types: (1) disclosed relevant information for COMPREHENSIVE planning (full fact-find; client wants recommendation); (2) disclosed relevant information for SPECIFIC-NEED(S) planning (partial fact-find; client wants recommendation); or (3) did NOT undergo any needs analysis and it is the client\'s own responsibility to ensure the selected product is suitable. Under type (3) it is mandatory to explain product features, fees and charges to the client, and the client must acknowledge the Application Type.', trap: 'Type 3 = no needs analysis; the client bears responsibility for suitability, but the representative must still explain product features, fees and charges.' },
      { id: 'h14-04', term: 'Fact-Find sections and their purposes', fact: 'Key sections: Important Notice to Client (identifies the adviser/representative and stresses accurate information); Personal Information (admin, preliminary product assessment, age for underwriting/pricing); Employment Details (DII eligibility, deferred period, occupational hazards, and income range for affordability); Spouse and Dependants (protection gaps and additional dependants like aged parents); Existing Health Policies (reference point to avoid replacement or over-insurance, especially under the Co-ordination of Benefit Clause); Personal Priorities; Health Condition (insurability); Replacement of Policy; Customer\'s Financials (affordability); and Adviser\'s Declaration (confidentiality under the Personal Data Protection Act 2012).', trap: 'DII is not issued to an unemployed person or anyone without a stable job; a self-employed person needs cover sooner (shorter deferred period) than an employee who may keep receiving pay.' },
      { id: 'h14-05', term: 'Vulnerable client and call-back', fact: 'Fact-Find information on language proficiency, educational level and accompaniment helps establish whether the client is vulnerable. For example, a client not proficient in written and spoken English and/or with only primary-school education may be considered vulnerable, and the representative\'s supervisor will make a call-back to ensure the client understood the recommendations and products applied for.' },
      { id: 'h14-06', term: 'Identifying needs - emergency fund and life stages', fact: 'When identifying needs the representative asks whether the client has an emergency fund, his employment status/occupation, life stage, dependants, existing cover, need for insurance, affordability and correct priorities. An emergency fund guards against the breadwinner\'s job loss or short-term disability interrupting family income and covers expenses insurance does not (e.g. a child\'s tuition); without one the client may be unable to service policies. Life stages run from childhood, young unmarried, young married/with children, married with older children, supporting aged parents, pre-retirement, to retirement. During active employment years it is crucial to protect earnings against disability; the need for protection against ill health applies to everyone, with older people needing more Critical Illness, Medical Expense and Long-Term Care Insurance.', trap: 'Protecting earnings against disability is most critical during the active employment years.' },
      { id: 'h14-07', term: 'Reviewing existing policies', fact: 'For an existing Disability Income policy, compare cover with current income, check whether it covers to target retirement age, the deferred period, and any employer disability benefit, and avoid over-insurance under the Limitation Clause. Life Insurance with TPD suits someone not actively employed (e.g. housewife). For Medical Expense Insurance, check ward entitlement, annual/lifetime limits, co-insurance and deductible, expiry age and renewability, and keep the Co-ordination of Benefit Clause in mind. For Critical Illness, check whether stand-alone or a rider, the payable percentage, and whether an Endowment CI terminates on maturity. Personal Accident: check coverage extent, exclusions and limitations. Long-Term Care: check the benefit trigger, ADL definitions and number of ADLs, and whether reimbursement-type. Hospital Cash pays ON TOP of all other Health Insurance plans.', trap: 'Hospital Cash Insurance pays on top of other health plans and is NOT subject to co-ordination of benefits; Medical Expense Insurance IS subject to the Co-ordination of Benefit Clause.' },
      { id: 'h14-08', term: 'Co-ordination of Benefit Clause', fact: 'Under the Co-ordination of Benefit Clause, when a bill is partly reimbursed by one plan, the amount claimable from the second plan is the MINIMUM of (i) the balance bill (total bill less what the first plan paid) or (ii) the amount covered under the second plan. In the text\'s example a S$22,400 bill with S$11,000 already paid by the group plan and S$12,000 coverable under the PMI results in a PMI claim of S$11,400 (the lower of the S$11,400 balance and S$12,000 coverable), so total received equals the actual S$22,400 and does not exceed the expenses incurred.', trap: 'The second-plan payout is the LOWER of the balance bill or its own coverable amount - total recovery can never exceed the actual expenses. This prevents profiting from insurance.' },
      { id: 'h14-09', term: 'Quantifying disability income protection needs (Maintenance Costs)', fact: 'Disability Income Protection Needs (also called Maintenance Costs) is the amount to meet ongoing daily living expenses of the client and dependants. Three methods: Method 1 uses 75% of monthly income less existing disability benefit; Method 2 uses total monthly expenses less existing disability benefit (the minimum needed to sustain living expenses); Method 3 provides a lump-sum TPD benefit (via a Life policy) for those who do not want/cannot afford/are ineligible for DII, computing yearly income needed times a present-value factor (adjusted for inflation) less funds available and existing insurance with TPD benefit.', trap: 'Method 1 caps DII at 75% of monthly income. In Method 3 only existing policies with a TPD benefit (e.g. Group Term Life, DPS) may be deducted from the funds required.' },
      { id: 'h14-10', term: 'Quantifying medical costs and hospital cash', fact: 'Medical costs are the immediate hospital and medical expenses from an injury or illness causing hospitalisation/surgery. To quantify, discuss the preferred hospital type and ward, premium affordability for co-payments (or self-insuring them), and continuous affordability when no longer working; MOH fee benchmarks help. Group Insurance is NOT portable and may be lost on leaving the organisation. Hospital Cash Insurance is quantified from total monthly expenses less existing hospital cash benefit, then divided by 30 days to get a daily amount (e.g. S$3,600 per month equals S$120 per day).', trap: 'Group Insurance is not portable - flag that the client may lose it on leaving the employer. Hospital cash daily benefit = monthly need divided by 30.' },
      { id: 'h14-11', term: 'Quantifying Critical Illness cover', fact: 'Quantifying CI cover is more art than science. Factors include which dread disease the client is most susceptible to (family history), family needs and level of dependence, whether he already has enough Medical Expense/DII, desired treatment level, choice between Additional Benefit Type and Acceleration Benefit Type, and personal preference. The Additional Benefit Type normally ceases at age 65, whereas the Acceleration Benefit Type (usually attached to a Whole Life policy) lasts for life. The shortfall equals the agreed CI cover less current CI cover held.', trap: 'Additional Benefit Type CI usually ceases at age 65; Acceleration Benefit Type (attached to Whole Life) lasts for life.' },
      { id: 'h14-12', term: 'Product recommendation principles and affordability', fact: 'Three basic principles before recommending: (a) recommend products only if he needs them; (b) recommend only the most suitable products given his circumstances; and (c) if he needs a product the company does not carry, tell him so he can find alternatives. Affordability is important because being able to afford the initial premium does not mean the client can sustain regular payments; for Medisave-funded policies, ensure the Medisave balance or future contributions can sustain the policy. Early lapse benefits no one - the client loses coverage, the representative loses goodwill and commission, and the insurer absorbs the high initial underwriting cost.' },
      { id: 'h14-13', term: 'Points on policy selection and presenting recommendations', fact: 'Policy-selection points: cover only the shortfall to minimise over-insurance; secure the longest coverage possible; ensure long-term premium affordability; insure the right life (breadwinner first); ensure sufficient death protection; use a rider if it saves premiums; discuss CI Additional vs Acceleration types and CI Waiver of Premium rider; ensure additional Medical Expense cover complements employer cover; and always check for alternative policies. Recommendations should be presented systematically: state the product\'s purpose (the need met), describe its nature, brief on benefits and limitations, explain the options, summarise reasons, explain the benefit illustration highlighting guaranteed and non-guaranteed benefits, and disclose distribution costs, charges and expenses.', trap: 'Needs quantification is an industry best practice, not mandatory; but disclosing the benefit illustration (guaranteed vs non-guaranteed) when presenting is expected.' },
      { id: 'h14-14', term: 'Periodic client review', fact: 'The process does not stop at initial implementation; the client\'s circumstances change and new needs surface. A review should be done on: (a) a change in personal circumstances (e.g. birth of a child); (b) external developments such as CPF ruling changes affecting the client\'s finances or product appropriateness; (c) the original products becoming inadequate to cover all needs; and (d) the launch of new products in the market.' },
    ],
  },
  {
    id: 'h15',
    num: 15,
    title: 'Case Studies',
    page: 325,
    concepts: [
      { id: 'h15-01', term: 'Case study purpose and reference guidelines', fact: 'The two case studies (individual and group Health Insurance) illustrate how the whole needs-based sales process is carried out; they are not a comprehensive guide for every situation. Representatives should keep abreast of the LIA and GIA Guidelines On Disclosure Requirements and Needs-Based Sales Process for A&H Insurance Products, and use MoneySENSE/LIA materials such as \'Your Guide To Health Insurance\' and the \'Evaluating My Health Insurance Coverage\' sheet.' },
      { id: 'h15-02', term: 'Principle - DII for the working breadwinner, TPD/PA for the non-working spouse', fact: 'The most suitable policy for maintenance cost is Disability Income Insurance, recommended at 75% of the breadwinner\'s monthly salary (in the case, S$4,500 on a S$6,000 income) with a deferred period matching how long the employer keeps paying salary (six months). A non-working spouse (housewife) is NOT eligible for DII, so disability protection is provided instead through the Total and Permanent Disability (TPD) benefit under a Life policy or through a Personal Accident policy.', trap: 'DII requires an income and a stable job; a housewife is ineligible and must be covered for disability via TPD (life) or Personal Accident instead.' },
      { id: 'h15-03', term: 'Principle - present value of maintenance income needs', fact: 'TPD/maintenance funds required = yearly income needed multiplied by a present-value annuity factor based on the real (inflation-adjusted) rate of return, less funds available and existing insurance with a TPD benefit. In the case, S$1,500 monthly expenses times 12 equals S$18,000 yearly, needed for 21 years, at a real return of 3% (5% return less 2% inflation), giving S$18,000 x 15.8775 = S$285,795, less S$0 existing = S$285,795 required.', trap: 'Use the REAL rate of return (nominal return minus inflation) to select the annuity factor, and deduct only existing policies that carry a TPD benefit.' },
      { id: 'h15-04', term: 'Principle - Group H&S is temporary, not lifetime', fact: 'Group Hospital & Surgical cover is NOT portable and may be lost or changed when the employee changes jobs or retires, so it should be treated as a temporary benefit, not a lifetime one. Because the individual Medical Expense Insurance and Group H&S are both subject to the Co-ordination of Benefits Clause, the client need not buy first-dollar cover on his individual plan; accepting a deductible and co-insurance lowers the premium and helps fund future (rising) premiums, but once the Group H&S is lost the co-payments must be met out-of-pocket.', trap: 'Because both plans co-ordinate benefits, first-dollar individual cover is often unnecessary; choosing a deductible/co-insurance lowers premium, at the cost of out-of-pocket payments once group cover ends.' },
      { id: 'h15-05', term: 'Principle - Acceleration CI packaged with Whole Life for lifelong cover', fact: 'Where clients already have death protection, a 100% Acceleration Benefit Type Critical Illness policy packaged with a Whole Life policy is recommended so cover lasts for life; for a non-working spouse this also provides the needed TPD cover. Non-guaranteed premium rates mean that with medical inflation the insurer will periodically update premium tables and premiums will rise, so future affordability (whether via Medisave or cash) must be discussed, not just present affordability.', trap: 'Acceleration CI attached to Whole Life gives lifelong cover (unlike Additional Benefit type ceasing at 65). Medical Expense premiums are non-guaranteed and rise with medical inflation.' },
      { id: 'h15-06', term: 'Principle - recommend within budget and only the shortfall', fact: 'The recommended package must fit the client\'s stated budget; in the case the total cash premium of S$695.50 stayed within the S$700 monthly budget, and Long-Term Care cover was not proposed because there was no spare premium for it. Recommendations should meet the client\'s objectives and only cover the shortfall, avoiding over-insurance.' },
      { id: 'h15-07', term: 'Principle - Group Term Life sum assured methods', fact: 'For Group Term Life, sum assured is commonly set either (a) according to rank or (b) as a number of times the employee\'s basic salary. The ranking method is easier to manage but ignores length of service; the salary-multiple method reflects length of service (more experienced staff earn more) and is generally more equitable. Attaching a 50% Acceleration Critical Illness rider to the Group Term Life keeps the benefit affordable when the company\'s budget is constrained.', trap: 'Ranking method is simpler but ignores tenure; salary-multiple method is more equitable because it reflects length of service.' },
      { id: 'h15-08', term: 'Principle - Group underwriting, claims history and no free-look', fact: 'Before quoting a group case, confirm the company meets underwriting requirements (group size, stability). The insurer cannot give a quotation until the Group Insurance Fact-Finding (GIFF) Form is duly completed and signed by both the client and the representative. Obtain the company\'s past three years of claims history plus probable IBNR, since claims history is very important in setting the premium. There is NO free-look period for any Group Insurance policy, and medical examinations must be arranged for any employee whose coverage falls outside the free cover limit.', trap: 'No free-look period applies to any Group Insurance policy. The insurer cannot quote until the GIFF Form is completed and signed by both client and representative.' },
    ],
  },
]
